// JSON-Schema-constrained decoding: compile a schema into a node tree, then
// validate generated bytes incrementally so sampling can reject any token
// that would break the schema. Properties are enforced in declared order
// (required ones mandatory, optional ones skippable), matching how
// grammar-based constrained decoding behaves elsewhere.
#include "schema.h"
#include "fpclass.h"
#include "schema_int.h"
#include "json.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <float.h>
#include <limits.h>
#include <math.h>

// ---------------------------------------------------------------- compile

// NULL on allocation failure. Every caller already propagates NULL as "this
// node did not compile", so the failure has a path home without a new
// convention; schema_compile supplies the message.
snode *sn_new(int kind) {
    snode *n = calloc(1, sizeof(snode));
    if (!n) return NULL;
    n->kind = kind;
    n->max_items = -1;
    return n;
}

// Serialise an enum/const literal. The builder latches `failed` on allocation
// failure and a NULL literal would be dereferenced later by union_start_bytes,
// pick_alt and emit_min_choice, so a failed dump must never reach n->lits.
static char *sn_literal(const jv *v) {
    sbuf lit = { 0 };
    jv_dump(v, &lit);
    if (lit.failed || !lit.s) { free(lit.s); return NULL; }
    return lit.s;
}

// An enum may be as long as a function has lines (the anchored-edit protocol
// enumerates them), so the walker cannot keep one bit per literal. It keeps a
// RANGE over the literals in sorted order instead: the candidates that match
// a prefix are always contiguous there. `order` is that permutation; the
// literal index the walker reports stays the declared one, which the
// discriminated tool action depends on.
#define SCHEMA_ENUM_MAX 4096
bool enum_index(snode *n) {
    free(n->order);
    n->order = malloc(sizeof(int) * (size_t)(n->n_lits > 0 ? n->n_lits : 1));
    if (!n->order) return false;
    for (int i = 0; i < n->n_lits; i++) {   // insertion sort: compile-time, small n
        int k = i;
        while (k > 0 && strcmp(n->lits[n->order[k - 1]], n->lits[i]) > 0) {
            n->order[k] = n->order[k - 1];
            k--;
        }
        n->order[k] = i;
    }
    return true;
}

void schema_free(snode *n) {
    if (!n) return;
    for (int i = 0; i < n->n_lits; i++) free(n->lits[i]);
    free(n->lits);
    free(n->order);
    for (int k = 0; k < n->n_pats; k++) {
        for (int i = 0; i < n->pats[k].n; i++) free(n->pats[k].seg[i].prefix);
        free(n->pats[k].seg);
    }
    free(n->pats);
    free(n->sentinel);
    for (int i = 0; i < n->n_props; i++) {
        if (n->keys) free(n->keys[i]);
        if (n->next_keys) free(n->next_keys[i]);
        schema_free(n->props[i]);
    }
    free(n->keys); free(n->key_len);
    free(n->next_keys); free(n->next_key_len);
    free(n->props); free(n->req);
    schema_free(n->items);
    for (int i = 0; i < n->n_alts; i++) schema_free(n->alts[i]);
    free(n->alts);
    free(n);
}


// ------------------------------------------------------- keyword gate
//
// The compiler enforces a fixed, small subset of JSON Schema. A keyword it
// does not implement must be a compile error rather than a silently weaker
// constraint: `pattern` dropped from a string leaves the value unconstrained
// in exactly the way the caller asked it not to be, which is worse than an
// error because it answers 200. Annotations are the one exemption — they
// carry no constraint, so ignoring one ignores nothing, and real OpenAI tool
// payloads are full of them.

static bool kw_in(const char *k, const char *const *list) {
    for (; *list; list++)
        if (!strcmp(k, *list)) return true;
    return false;
}

static const char *const KW_ANNOTATION[] = {
    "title", "description", "$comment", "$schema", "$id", "examples",
    "default", "deprecated", "readOnly", "writeOnly", "format", NULL
};
static const char *const KW_STRING[] = { "minLength", "maxLength", "pattern", NULL };
static const char *const KW_ARRAY[]  = { "items", "minItems", "maxItems", NULL };
static const char *const KW_OBJECT[] = { "properties", "required",
                                         "additionalProperties", "propertyNames",
                                         NULL };
static const char *const KW_INTEGER[] = { "minimum", "maximum",
                                          "exclusiveMinimum", "exclusiveMaximum",
                                          NULL };

// does `s` declare (or imply) type `want`? mirrors compile_node's dispatch
static bool declares_type(jv *s, const char *want) {
    jv *ty = jv_get(s, "type");
    if (ty && ty->type == J_STR) return !strcmp(ty->str, want);
    if (ty && ty->type == J_ARR) {
        for (int i = 0; i < ty->n; i++)
            if (!strcmp(jv_str(ty->items[i], "?"), want)) return true;
        return false;
    }
    if (ty) return false;
    if (jv_get(s, "properties")) return !strcmp(want, "object");
    if (jv_get(s, "items"))      return !strcmp(want, "array");
    return false;
}

/* `allOf` is admitted in exactly one shape: on a string, with every member
   a string constraint (pattern, minLength, maxLength, a `type` that agrees,
   annotations). Its meaning there is a conjunction the string node can
   enforce exactly -- every pattern, the tightest bounds. Claude Code 2.1.272
   declares `{"allOf":[{"pattern":...},{"pattern":...}]}` on a tool
   parameter and was answered 400 on every request. Any other allOf (object
   fragments to merge, mixed types) stays refused by name. */
static bool allof_is_string_conjunction(jv *s, char *err, int errcap) {
    jv *all = jv_get(s, "allOf");
    if (!all) return true;
    if (all->type != J_ARR || all->n < 1) {
        snprintf(err, errcap, "allOf must be a non-empty array");
        return false;
    }
    if (!declares_type(s, "string")) {
        snprintf(err, errcap, "unsupported schema keyword 'allOf' (only string "
                              "constraints can be conjoined)");
        return false;
    }
    for (int i = 0; i < all->n; i++) {
        jv *m = all->items[i];
        if (!m || m->type != J_OBJ) {
            snprintf(err, errcap, "allOf members must be objects");
            return false;
        }
        for (int k = 0; k < m->n; k++) {
            const char *key = m->keys[k];
            if (kw_in(key, KW_ANNOTATION) || kw_in(key, KW_STRING)) continue;
            if (!strcmp(key, "type")) {
                if (!declares_type(m, "string")) {
                    snprintf(err, errcap, "allOf member declares a type other "
                                          "than the string it constrains");
                    return false;
                }
                continue;
            }
            snprintf(err, errcap, "unsupported schema keyword '%.40s' in allOf", key);
            return false;
        }
    }
    return true;
}

static bool check_keywords(jv *s, char *err, int errcap) {
    if (!s || s->type != J_OBJ) return true;
    bool one = jv_get(s, "oneOf") != NULL, any = jv_get(s, "anyOf") != NULL;
    if (one && any) {
        snprintf(err, errcap, "keyword 'anyOf' cannot be combined with 'oneOf'");
        return false;
    }
    if (!allof_is_string_conjunction(s, err, errcap)) return false;
    bool composed = one || any;
    bool literal  = !composed &&
                    (jv_get(s, "enum") != NULL || jv_get(s, "const") != NULL);
    for (int i = 0; i < s->n; i++) {
        const char *k = s->keys[i];
        if (kw_in(k, KW_ANNOTATION)) continue;
        if (!strcmp(k, "type")) continue;
        if (!strcmp(k, "allOf") && !composed && !literal) continue;
        bool ok;
        if (composed)     ok = !strcmp(k, "oneOf") || !strcmp(k, "anyOf");
        else if (literal) ok = !strcmp(k, "enum") || !strcmp(k, "const");
        else ok = (declares_type(s, "string")  && kw_in(k, KW_STRING)) ||
                  (declares_type(s, "array")   && kw_in(k, KW_ARRAY))  ||
                  (declares_type(s, "object")  && kw_in(k, KW_OBJECT)) ||
                  (declares_type(s, "number")  && kw_in(k, KW_INTEGER)) ||
                  (declares_type(s, "integer") && kw_in(k, KW_INTEGER));
        if (!ok) {
            snprintf(err, errcap,
                     "unsupported schema keyword '%.40s'", k);
            return false;
        }
    }
    return true;
}

// `additionalProperties` and a `required` list are the two object keywords
// whose absence changes what the compiled machine accepts, so they get rules
// beyond the name check. Fixed-property objects are closed; objects with no
// declared properties may instead be open/unconstrained or homogeneous maps.
// A mixed fixed/open object cannot be represented by the streaming machine
// and must be rejected rather than silently narrowed or weakened.
static bool check_object_rules(jv *s, char *err, int errcap) {
    jv *props = jv_get(s, "properties");
    if (props && props->type != J_OBJ) {
        // Everything below reads `properties` as a member map. A `properties`
        // that is not one used to fall through to the open-object machine,
        // which accepts any object at all -- a declared constraint quietly
        // becoming no constraint, which is the outcome this compiler exists
        // to prevent.
        snprintf(err, errcap, "properties must be an object");
        return false;
    }
    bool has_props = props && props->type == J_OBJ && props->n > 0;
    bool no_declared = !props || (props->type == J_OBJ && props->n == 0);
    jv *ap = jv_get(s, "additionalProperties");
    bool closed_schema = ap && ap->type == J_BOOL && !ap->b &&
                         (!props || props->type == J_OBJ);
    bool open_schema = no_declared &&
                       ((ap && ap->type == J_BOOL && ap->b) ||
                        (ap && ap->type == J_OBJ));
    if (ap && !open_schema &&
        !closed_schema) {
        snprintf(err, errcap,
                 "additionalProperties is only supported as false alongside "
                 "declared properties, or as an open schema without them");
        return false;
    }
    jv *pn = jv_get(s, "propertyNames");
    if (pn) {
        // JSON object member names are strings by construction, so this exact
        // schema adds no constraint. Any narrower propertyNames schema would.
        jv *ty = pn->type == J_OBJ ? jv_get(pn, "type") : NULL;
        if (!ty || ty->type != J_STR || strcmp(ty->str, "string") || pn->n != 1) {
            snprintf(err, errcap,
                     "propertyNames is only supported as {\"type\":\"string\"}");
            return false;
        }
    }
    jv *req = jv_get(s, "required");
    if (req && req->type != J_ARR) {
        snprintf(err, errcap, "required must be an array");
        return false;
    }
    if (req && req->n > 0 && !has_props) {
        // without properties the object compiles to the generic any-object
        // machine, which cannot enforce a required key at all
        snprintf(err, errcap,
                 "required needs a properties map to constrain");
        return false;
    }
    return true;
}

bool compile_bound(jv *v, int dflt, int *out) {
    if (!v) { *out = dflt; return true; }
    if (v->type != J_NUM || v->num < 0 || v->num > INT_MAX ||
        floor(v->num) != v->num)
        return false;
    *out = (int)v->num;
    return true;
}

/* Compile the anchored prefix + ASCII class form used by coding-agent IDs,
   e.g. ^wf_[a-z0-9-]{6,}$. The class may be written as a bracket set or as the
   \d / \w shorthand, so ^\d{5}$ — a postal code, an order number, an ID, the
   single most common fixed-length pattern there is — compiles rather than
   being refused for a spelling. Other regex forms remain explicit errors.

   Both halves are matched LITERALLY at runtime, so any regex syntax we would
   silently reinterpret must be a compile error instead: a metacharacter in
   the prefix (`.` `\` `$` ...), a negated class (`[^a]`), or an escape INSIDE
   a bracket set (`[\d]`) would make the enforced language differ from the
   declared pattern — and a constraint that differs from the one the caller
   declared is the exact failure this compiler exists to prevent. */
static bool pattern_prefix_char_ok(unsigned char c) {
    if (c >= 128) return false;
    return strchr(".\\*+?()|{}$^", (char)c) == NULL;
}

/* The shorthand classes, expanded to exactly the sets the regex means. \d
   and \w are printable ASCII. \s is the six whitespace characters; five of
   them are control characters a JSON string only carries escaped, and this
   validator admits no escape inside a pattern, so the space is the one
   producible member -- which is the restriction every class here has always
   carried (a `"` in a set was never producible either): the enforced language
   is the declared one restricted to what a JSON string spells literally.
   \S, \D and \W are the complements, and admit every non-ASCII character.
   Adds to `ascii`/`*non_ascii`; the caller starts from an empty set. */
static bool pattern_shorthand_class(char c, bool *ascii, bool *non_ascii) {
    bool set[128] = {0};
    switch (c) {
        case 'd': case 'D':
            for (unsigned x = '0'; x <= '9'; x++) set[x] = true;
            break;
        case 'w': case 'W':
            for (unsigned x = '0'; x <= '9'; x++) set[x] = true;
            for (unsigned x = 'A'; x <= 'Z'; x++) set[x] = true;
            for (unsigned x = 'a'; x <= 'z'; x++) set[x] = true;
            set['_'] = true;
            break;
        case 's': case 'S':
            set[' '] = set['\t'] = set['\n'] = set['\r'] = set['\f'] = set['\v'] = true;
            break;
        default:
            return false;
    }
    bool negate = c == 'D' || c == 'W' || c == 'S';
    for (unsigned x = 0; x < 128; x++) if (set[x] != negate) ascii[x] = true;
    if (negate) *non_ascii = true;
    return true;
}

/* A character a JSON string can spell without an escape and this validator
   therefore lets a pattern class produce: printable ASCII other than the
   quote and the backslash. Every class must contain at least one, or no
   forced completion could ever fill it. */
static bool pattern_producible(unsigned c) {
    return c >= 0x20 && c < 0x7f && c != '"' && c != '\\';
}

/* What the compiled pattern allows at byte offset `pos`. The validator and
   the truncation closer both ask this rather than re-deriving segment
   boundaries, so they cannot disagree about where a class begins. */
typedef enum { PAT_LIT, PAT_CLASS, PAT_END, PAT_NONE } pat_what;
typedef struct { pat_what what; unsigned char lit; bool ascii[128]; bool non_ascii; } pat_at;

/* What ONE compiled pattern allows at byte offset `pos`. */
static pat_at pattern_at_pos(const pattern *p, int pos) {
    pat_at r = { PAT_END, 0, {0}, false };
    for (int i = 0; i < p->n; i++) {
        const pat_seg *g = &p->seg[i];
        if (pos < g->prefix_len) {
            r.what = PAT_LIT; r.lit = (unsigned char)g->prefix[pos];
            return r;
        }
        pos -= g->prefix_len;
        if (!g->has_class) continue;
        /* every segment but the last is fixed-length, so its span is exactly
           min_tail; the last may run to max_tail, or forever when unbounded */
        int span = (i + 1 < p->n) ? g->min_tail : g->max_tail;
        if (span < 0 || pos < span) {
            r.what = PAT_CLASS;
            memcpy(r.ascii, g->ascii, sizeof(r.ascii));
            r.non_ascii = g->non_ascii;
            return r;
        }
        pos -= span;
    }
    return r;
}

/* What every pattern of the node allows at `pos`, together: the literal
   they agree on, the intersection of their classes, END when any of them
   is complete (the others may admit more, but the string cannot carry it),
   NONE when they contradict. The validator and the truncation closer both
   ask this rather than re-deriving segment boundaries, so they cannot
   disagree about where a class begins. */
static pat_at pat_at_pos(const snode *n, int pos) {
    pat_at r = { PAT_CLASS, 0, {0}, true };
    memset(r.ascii, 1, sizeof(r.ascii));
    for (int k = 0; k < n->n_pats; k++) {
        pat_at a = pattern_at_pos(&n->pats[k], pos);
        if (a.what == PAT_END) { r.what = PAT_END; return r; }
        if (a.what == PAT_LIT) {
            bool ok = r.what == PAT_LIT ? r.lit == a.lit : r.ascii[a.lit];
            if (!ok) { r.what = PAT_NONE; return r; }
            r.what = PAT_LIT; r.lit = a.lit;
            continue;
        }
        if (r.what == PAT_LIT) {
            if (!a.ascii[r.lit]) { r.what = PAT_NONE; return r; }
            continue;
        }
        for (unsigned c = 0; c < 128; c++) r.ascii[c] = r.ascii[c] && a.ascii[c];
        r.non_ascii = r.non_ascii && a.non_ascii;
    }
    return r;
}

/* The byte a forced completion writes at offset `pos`: the literal the
   patterns require there, or the lowest producible member of the class they
   allow. One function so the closer cannot drift from the validator. */
static unsigned char pat_fill_byte(const snode *n, int pos) {
    pat_at at = pat_at_pos(n, pos);
    if (at.what == PAT_LIT) return at.lit;
    if (at.what == PAT_CLASS) {
        for (unsigned c = 0; c < 128; c++)
            if (at.ascii[c] && pattern_producible(c)) return (unsigned char)c;
    }
    return ' ';   /* unreachable for a compiled pattern: every class is non-empty */
}

/* Shortest and longest strings the patterns admit together (the longest of
   the minimums, the shortest of the maximums); -1 max means unbounded. These
   are what minLength/maxLength are checked against, and what the closer must
   reach before it may emit the closing quote. */
static int pattern_min_len(const pattern *p) {
    int total = 0;
    for (int i = 0; i < p->n; i++)
        total += p->seg[i].prefix_len + (p->seg[i].has_class ? p->seg[i].min_tail : 0);
    return total;
}

static int pattern_max_len(const pattern *p) {
    int total = 0;
    for (int i = 0; i < p->n; i++) {
        total += p->seg[i].prefix_len;
        if (!p->seg[i].has_class) continue;
        if (p->seg[i].max_tail < 0) return -1;
        total += p->seg[i].max_tail;
    }
    return total;
}

static int pat_min_len(const snode *n) {
    int best = 0;
    for (int k = 0; k < n->n_pats; k++) {
        int m = pattern_min_len(&n->pats[k]);
        if (m > best) best = m;
    }
    return best;
}

static int pat_max_len(const snode *n) {
    int best = -1;
    for (int k = 0; k < n->n_pats; k++) {
        int m = pattern_max_len(&n->pats[k]);
        if (m >= 0 && (best < 0 || m < best)) best = m;
    }
    return best;
}

/* Parse one `{n}` / `{n,}` / `{n,m}` / `+` quantifier at `q`. Returns the
   first byte after it, or NULL if this is not a quantifier this compiler can
   enforce exactly. */
static const char *parse_quantifier(const char *q, long *min, long *max) {
    if (*q == '+') { *min = 1; *max = -1; return q + 1; }
    if (*q == '*') { *min = 0; *max = -1; return q + 1; }
    if (*q != '{') return NULL;
    char *end = NULL;
    *min = strtol(q + 1, &end, 10);
    if (*min < 0 || *min > INT_MAX || !end || end == q + 1) return NULL;
    if (*end == '}') { *max = *min; return end + 1; }            /* {n}   */
    if (*end != ',') return NULL;
    if (end[1] == '}') { *max = -1; return end + 2; }            /* {n,}  */
    char *end2 = NULL;                                           /* {n,m} */
    *max = strtol(end + 1, &end2, 10);
    if (*max < 0 || *max > INT_MAX || !end2 || end2 == end + 1 || *end2 != '}')
        return NULL;
    /* an empty language is a schema the caller cannot ever satisfy, and
       silently accepting it would deadlock decoding rather than fail */
    if (*max < *min) return NULL;
    return end2 + 1;
}

/* Compile `^ ( literal class{q} )* literal? $` into segments.

   Several segments are accepted only while every one before the last is
   fixed-length. With `^[A-Z]{3}[0-9]{4}$` the class holding byte 4 follows
   from the offset alone; with `^[A-Z]{1,3}[0-9]{2}$` it does not, and a
   compiler that guessed would enforce a language the caller did not
   declare -- the exact failure this file exists to prevent. */
/* One member of a bracket set: a literal, a range, or an escape. Adds to
   `ascii`/`*non_ascii` and returns the byte after the member, or NULL for
   syntax this compiler cannot enforce exactly. */
static const char *class_member(const char *q, const char *rb, bool *ascii,
                                bool *non_ascii) {
    unsigned char lo, hi;
    if (*q == '\\') {
        if (q + 1 >= rb) return NULL;
        unsigned char e = (unsigned char)q[1];
        if (pattern_shorthand_class((char)e, ascii, non_ascii)) return q + 2;
        switch (e) {
            case 'n': lo = '\n'; break;
            case 'r': lo = '\r'; break;
            case 't': lo = '\t'; break;
            case 'f': lo = '\f'; break;
            case 'v': lo = '\v'; break;
            default:
                /* an escaped punctuation character stands for itself */
                if (e >= 128 || ((e >= 'a' && e <= 'z') || (e >= 'A' && e <= 'Z') ||
                                 (e >= '0' && e <= '9')))
                    return NULL;
                lo = e;
        }
        ascii[lo] = true;
        return q + 2;
    }
    lo = hi = (unsigned char)*q;
    if (lo >= 128) return NULL;
    const char *next = q + 1;
    if (next + 1 < rb && *next == '-') {
        if (next[1] == '\\' || (unsigned char)next[1] >= 128) return NULL;
        hi = (unsigned char)next[1];
        next += 2;
    }
    if (hi < lo) return NULL;
    for (unsigned c = lo; c <= hi; c++) ascii[c] = true;
    return next;
}

static bool compile_ascii_pattern_value(jv *pv, snode *n, char *err, int errcap);

static bool compile_ascii_pattern(jv *s, snode *n, char *err, int errcap) {
    jv *pv = jv_get(s, "pattern");
    if (!pv) return true;
    return compile_ascii_pattern_value(pv, n, err, errcap);
}

static bool compile_ascii_pattern_value(jv *pv, snode *n, char *err, int errcap) {
    /* declared before the first failure exit: the unwind path frees the
       prefixes owned so far, so the count has to be live from the start */
    pat_seg segs[8];
    int n_segs = 0;
    if (pv->type != J_STR) goto bad;
    const char *p = pv->str;
    if (*p++ != '^') goto bad;

    while (*p && strcmp(p, "$") != 0) {
        if (n_segs == (int)(sizeof(segs) / sizeof(*segs))) goto bad;
        pat_seg *g = &segs[n_segs];
        memset(g, 0, sizeof(*g));

        /* literal run: up to the next class token, or to the closing `$` */
        const char *lb  = strchr(p, '[');
        const char *esc = strchr(p, '\\');
        bool shorthand  = esc && (!lb || esc < lb);
        const char *cls = shorthand ? esc : lb;
        for (const char *q = p; q < (cls ? cls : p + strlen(p) - 1); q++)
            if (!pattern_prefix_char_ok((unsigned char)*q)) goto bad;
        int plen = (int)((cls ? cls : p + strlen(p) - 1) - p);
        g->prefix_len = plen;
        g->prefix = strndup(p, (size_t)plen);
        if (!g->prefix) goto oom;
        n_segs++;                       /* owned from here: unwind on failure */

        if (!cls) { p += plen; break; } /* trailing literal, then `$` */
        p += plen;

        const char *quant;
        if (shorthand) {
            if (!pattern_shorthand_class(esc[1], g->ascii, &g->non_ascii)) goto bad;
            quant = esc + 2;
        } else {
            /* the set's closing bracket: the first `]` not escaped, and not
               the one a set may open with (`[]a]` means `]` and `a`) */
            const char *q = lb + 1;
            bool negate = *q == '^';
            if (negate) q++;
            const char *rb = q;
            if (*rb == ']') rb++;
            for (; *rb && *rb != ']'; rb++) if (*rb == '\\' && rb[1]) rb++;
            if (*rb != ']') goto bad;
            if (rb == q) goto bad;        /* an empty set matches nothing: unsatisfiable */
            while (q < rb) {
                q = class_member(q, rb, g->ascii, &g->non_ascii);
                if (!q) goto bad;
            }
            if (negate) {
                /* the complement: every ASCII character not named, and
                   every non-ASCII one */
                for (unsigned c = 0; c < 128; c++) g->ascii[c] = !g->ascii[c];
                g->non_ascii = !g->non_ascii;
            }
            quant = rb + 1;
        }
        /* a class no JSON string can spell a member of (control characters
           only, or the quote) leaves a forced completion nothing to write */
        bool producible = false;
        for (unsigned c = 0; c < 128 && !producible; c++)
            producible = g->ascii[c] && pattern_producible(c);
        if (!producible) goto bad;
        long min = 0, max = -1;
        const char *after = parse_quantifier(quant, &min, &max);
        if (!after) goto bad;
        g->has_class = true;
        g->min_tail  = (int)min;
        g->max_tail  = (int)max;
        p = after;
    }
    if (strcmp(p, "$") != 0) goto bad;
    if (!n_segs) goto bad;
    /* At least one repeated class. A pattern that is only a literal (`^x$`)
       is exactly enforceable, but it has always been refused here and both
       the tool-envelope test and the conformance matrix pin that: widening
       what this compiler accepts is a contract change, not a side effect of
       teaching it a second class. */
    bool any_class = false;
    for (int i = 0; i < n_segs; i++) any_class |= segs[i].has_class;
    if (!any_class) goto bad;
    /* only the last segment may be variable-length: see the note above */
    for (int i = 0; i + 1 < n_segs; i++)
        if (segs[i].has_class && segs[i].max_tail != segs[i].min_tail) goto bad;

    {
        pattern *grown = realloc(n->pats, sizeof(*n->pats) * (size_t)(n->n_pats + 1));
        if (!grown) goto oom;
        n->pats = grown;
        pattern *pat = &n->pats[n->n_pats];
        pat->seg = calloc((size_t)n_segs, sizeof(*pat->seg));
        if (!pat->seg) goto oom;
        memcpy(pat->seg, segs, (size_t)n_segs * sizeof(*pat->seg));
        pat->n = n_segs;
        n->n_pats++;
    }
    return true;
oom:
    for (int i = 0; i < n_segs; i++) free(segs[i].prefix);
    return false;
bad:
    for (int i = 0; i < n_segs; i++) free(segs[i].prefix);
    snprintf(err, errcap,
             "pattern only supports an anchored sequence of literal runs and "
             "repeated classes ([...], [^...], \\d, \\w, \\s and their "
             "complements), where every class before the last has a fixed "
             "count (got %s)",
             pv->type == J_STR ? pv->str : "a non-string");
    return false;
}

/* Every pattern of a string node holds at once, so their conjunction must
   admit some string: a position where they contradict (`[a-z]` against
   `[0-9]`, or two different literals) before the shortest string they
   jointly require is an empty language, refused here rather than wedging a
   request with no admissible byte. */
static bool patterns_consistent(const snode *n, char *err, int errcap) {
    int need = pat_min_len(n), cap = pat_max_len(n);
    if (cap >= 0 && need > cap) {
        snprintf(err, errcap, "allOf patterns cannot be satisfied together");
        return false;
    }
    for (int pos = 0; pos < need; pos++) {
        pat_at at = pat_at_pos(n, pos);
        bool ok = at.what == PAT_LIT;
        if (at.what == PAT_CLASS)
            for (unsigned c = 0; c < 128 && !ok; c++)
                ok = at.ascii[c] && pattern_producible(c);
        if (!ok) {
            snprintf(err, errcap, "allOf patterns cannot be satisfied together");
            return false;
        }
    }
    return true;
}

#define JSON_SAFE_INTEGER 9007199254740991LL

enum numeric_keyword_state {
    NUMERIC_ABSENT,
    NUMERIC_VALID,
    NUMERIC_INVALID,
};

static enum numeric_keyword_state numeric_keyword(jv *s, const char *key,
                                                   double *out) {
    jv *v = jv_get(s, key);
    if (!v) return NUMERIC_ABSENT;
    if (v->type != J_NUM || !fp_isfinite(v->num) ||
        v->num < -(double)JSON_SAFE_INTEGER ||
        v->num >  (double)JSON_SAFE_INTEGER)
        return NUMERIC_INVALID;
    *out = v->num;
    return NUMERIC_VALID;
}

static bool compile_integer_bounds(jv *s, snode *n, char *err, int errcap) {
    double x;
    enum numeric_keyword_state state = numeric_keyword(s, "minimum", &x);
    if (state == NUMERIC_INVALID) goto bad;
    if (state == NUMERIC_VALID) {
        n->num_min = (int64_t)ceil(x);
        n->has_num_min = true;
    }
    state = numeric_keyword(s, "exclusiveMinimum", &x);
    if (state == NUMERIC_INVALID) goto bad;
    if (state == NUMERIC_VALID) {
        int64_t v = (int64_t)floor(x) + 1;
        if (!n->has_num_min || v > n->num_min) n->num_min = v;
        n->has_num_min = true;
    }
    state = numeric_keyword(s, "maximum", &x);
    if (state == NUMERIC_INVALID) goto bad;
    if (state == NUMERIC_VALID) {
        n->num_max = (int64_t)floor(x);
        n->has_num_max = true;
    }
    state = numeric_keyword(s, "exclusiveMaximum", &x);
    if (state == NUMERIC_INVALID) goto bad;
    if (state == NUMERIC_VALID) {
        int64_t v = (int64_t)ceil(x) - 1;
        if (!n->has_num_max || v < n->num_max) n->num_max = v;
        n->has_num_max = true;
    }
    if (n->has_num_min && n->has_num_max && n->num_min > n->num_max) {
        snprintf(err, errcap, "empty integer bounds");
        return false;
    }
    return true;
bad:
    snprintf(err, errcap, "integer bounds must be finite JSON-safe numbers");
    return false;
}

static bool compile_number_bounds(jv *s, snode *n, char *err, int errcap) {
    double x;
    enum numeric_keyword_state state = numeric_keyword(s, "minimum", &x);
    if (state == NUMERIC_INVALID) goto bad;
    if (state == NUMERIC_VALID) {
        n->real_min = x; n->has_real_min = true;
    }
    state = numeric_keyword(s, "exclusiveMinimum", &x);
    if (state == NUMERIC_INVALID) goto bad;
    if (state == NUMERIC_VALID) {
        // INTERSECT with `minimum`, never replace it. A schema carrying both
        // keywords means both, and overwriting let whichever was written
        // second win -- so `{"minimum":10,"exclusiveMinimum":5}` accepted 7,
        // a value the caller declared out of range. compile_integer_bounds
        // has always taken the tighter of the two; this is the same rule for
        // the real-valued arm.
        double v = nextafter(x, DBL_MAX);
        if (!n->has_real_min || v > n->real_min) n->real_min = v;
        n->has_real_min = true;
    }
    state = numeric_keyword(s, "maximum", &x);
    if (state == NUMERIC_INVALID) goto bad;
    if (state == NUMERIC_VALID) {
        n->real_max = x; n->has_real_max = true;
    }
    state = numeric_keyword(s, "exclusiveMaximum", &x);
    if (state == NUMERIC_INVALID) goto bad;
    if (state == NUMERIC_VALID) {
        double v = nextafter(x, -DBL_MAX);
        if (!n->has_real_max || v < n->real_max) n->real_max = v;
        n->has_real_max = true;
    }
    if (n->has_real_min && n->has_real_max && n->real_min > n->real_max) {
        snprintf(err, errcap, "empty number bounds");
        return false;
    }
    return true;
bad:
    snprintf(err, errcap, "number bounds must be finite JSON-safe numbers");
    return false;
}

static bool plain_key(const char *s) {
    for (const unsigned char *p = (const unsigned char *)s; *p; p++)
        if (*p < 0x20 || *p == '"' || *p == '\\') return false;
    return true;
}

static int prop_index(jv *props, const char *key) {
    if (!props || props->type != J_OBJ) return -1;
    for (int i = 0; i < props->n; i++)
        if (!strcmp(props->keys[i], key)) return i;
    return -1;
}

static bool same_prop_order(jv *a, jv *b) {
    if (!a || !b || a->type != J_OBJ || b->type != J_OBJ || a->n != b->n)
        return false;
    for (int i = 0; i < a->n; i++)
        if (strcmp(a->keys[i], b->keys[i]) != 0) return false;
    return true;
}

// The discriminator: one literal per alternative's `tool` const, in
// declared order, each distinct.
static snode *discriminator_literals(jv *alts, int tool_i, char *err, int errcap) {
    snode *tool = sn_new(SN_ENUM);
    if (!tool) return NULL;
    tool->lits = calloc(alts->n, sizeof(char *));
    if (!tool->lits) { schema_free(tool); return NULL; }
    for (int a = 0; a < alts->n; a++) {
        jv *props = jv_get(alts->items[a], "properties");
        char *lit = sn_literal(jv_get(props->items[tool_i], "const"));
        if (!lit) { schema_free(tool); return NULL; }
        for (int prev = 0; prev < a; prev++) {
            if (!strcmp(tool->lits[prev], lit)) {
                free(lit);
                snprintf(err, errcap, "duplicate discriminator const");
                schema_free(tool);
                return NULL;
            }
        }
        tool->lits[tool->n_lits++] = lit;
    }
    if (!enum_index(tool)) { schema_free(tool); return NULL; }
    return tool;
}

// The arguments: one alternative per branch, chosen by the discriminator.
static snode *discriminated_args(jv *alts, int args_i, char *err, int errcap,
                                 int depth) {
    snode *args = sn_new(SN_COND);
    if (!args) return NULL;
    args->alts = calloc(alts->n, sizeof(snode *));
    if (!args->alts) { schema_free(args); return NULL; }
    for (int a = 0; a < alts->n; a++) {
        jv *props = jv_get(alts->items[a], "properties");
        args->alts[args->n_alts] = compile_node(props->items[args_i], err, errcap,
                                                depth + 1);
        if (!args->alts[args->n_alts]) {
            schema_free(args);
            return NULL;
        }
        args->n_alts++;
    }
    return args;
}

// Every alternative declares alternative 0's `required` list, key for key.
static bool same_required_sets(jv *alts, jv *req, char *err, int errcap) {
    for (int a = 1; a < alts->n; a++) {
        jv *other = jv_get(alts->items[a], "required");
        int rn = req && req->type == J_ARR ? req->n : 0;
        int on = other && other->type == J_ARR ? other->n : 0;
        bool same = rn == on;
        for (int r = 0; same && r < rn; r++) {
            const char *k0 = jv_str(req->items[r], NULL);
            const char *k1 = jv_str(other->items[r], NULL);
            same = k0 && k1 && !strcmp(k0, k1);
        }
        if (!same) {
            snprintf(err, errcap, "oneOf alternatives declare different required keys");
            return false;
        }
    }
    return true;
}

static snode *compile_discriminated_action(jv *alts, char *err, int errcap,
                                           int depth, bool *matched) {
    *matched = false;
    if (alts->n <= 0 || alts->n > 60) return NULL;

    jv *first_props = jv_get(alts->items[0], "properties");
    if (!first_props || first_props->type != J_OBJ) return NULL;
    if (first_props->n <= 0 || first_props->n > 60) return NULL;
    int tool_i = prop_index(first_props, "tool");
    int args_i = prop_index(first_props, "args");
    if (tool_i < 0 || args_i < 0) return NULL;
    if (args_i < tool_i) {
        *matched = true;
        snprintf(err, errcap, "tool discriminator must precede args");
        return NULL;
    }

    for (int a = 0; a < alts->n; a++) {
        jv *props = jv_get(alts->items[a], "properties");
        if (!same_prop_order(first_props, props)) return NULL;
        jv *cn = jv_get(props->items[tool_i], "const");
        if (!cn || (cn->type != J_STR && cn->type != J_NUM &&
                    cn->type != J_BOOL && cn->type != J_NULL))
            return NULL;
    }

    // Alternatives on this path are consumed field by field rather than
    // through compile_node, so the keyword gate has to be applied here too —
    // otherwise `pattern` on a tool branch would be dropped exactly where a
    // strict tool call needs it most.
    *matched = true;
    for (int a = 0; a < alts->n; a++) {
        if (!check_keywords(alts->items[a], err, errcap) ||
            !check_object_rules(alts->items[a], err, errcap))
            return NULL;
    }
    snode *n = sn_new(SN_OBJ);
    if (!n) return NULL;
    n->keys    = calloc(first_props->n, sizeof(char *));
    n->key_len = calloc(first_props->n, sizeof(int));
    n->props   = calloc(first_props->n, sizeof(snode *));
    n->req     = calloc(first_props->n, sizeof(bool));
    if (!n->keys || !n->key_len || !n->props || !n->req) { schema_free(n); return NULL; }
    // published only now: schema_free walks keys[]/props[] n_props times, so a
    // count set before the arrays exist would make the cleanup path the crash
    n->n_props = first_props->n;

    for (int i = 0; i < first_props->n; i++) {
        if (!plain_key(first_props->keys[i])) {
            snprintf(err, errcap, "property keys needing JSON escapes are unsupported");
            schema_free(n);
            return NULL;
        }
        n->keys[i] = strdup(first_props->keys[i]);
        if (!n->keys[i]) { schema_free(n); return NULL; }
        n->key_len[i] = (int)strlen(first_props->keys[i]);
    }

    snode *tool = discriminator_literals(alts, tool_i, err, errcap);
    if (!tool) { schema_free(n); return NULL; }
    n->props[tool_i] = tool;

    snode *args = discriminated_args(alts, args_i, err, errcap, depth);
    if (!args) { schema_free(n); return NULL; }
    n->props[args_i] = args;

    for (int i = 0; i < first_props->n; i++) {
        if (i == tool_i || i == args_i) continue;
        n->props[i] = compile_node(first_props->items[i], err, errcap, depth + 1);
        if (!n->props[i]) { schema_free(n); return NULL; }
    }

    jv *req = jv_get(alts->items[0], "required");
    if (req && req->type == J_ARR) {
        for (int r = 0; r < req->n; r++) {
            const char *k = jv_str(req->items[r], NULL);
            bool found = false;
            for (int i = 0; i < first_props->n && k; i++)
                if (!strcmp(n->keys[i], k)) { n->req[i] = true; found = true; }
            if (!found) {
                snprintf(err, errcap, "required key '%s' not in properties",
                         k ? k : "?");
                schema_free(n);
                return NULL;
            }
        }
    }
    // the compiled object carries one required set, so every alternative
    // must declare the same one — a per-branch difference would be enforced
    // as alternative 0's rules on all branches
    if (!same_required_sets(alts, req, err, errcap)) { schema_free(n); return NULL; }
    return n;
}

// A string: its length bounds, its pattern, and the string constraints an
// allOf adds.
static snode *compile_string(jv *s, char *err, int errcap) {
    snode *n = sn_new(SN_STR);
    if (!n) return NULL;
    jv *mn = jv_get(s, "minLength"), *mx = jv_get(s, "maxLength");
    if (!compile_bound(mn, 0, &n->min_items) ||
        !compile_bound(mx, -1, &n->max_items) ||
        (n->max_items >= 0 && n->min_items > n->max_items)) {
        snprintf(err, errcap, "invalid string length bounds");
        schema_free(n);
        return NULL;
    }
    if (!compile_ascii_pattern(s, n, err, errcap)) {
        schema_free(n);
        return NULL;
    }
    // allOf of string constraints: every member's pattern is one more
    // pattern the string must satisfy, its bounds tighten the node's.
    // check_keywords admitted only string keywords in the members.
    jv *all = jv_get(s, "allOf");
    for (int i = 0; all && i < all->n; i++) {
        jv *m = all->items[i];
        jv *pv = jv_get(m, "pattern");
        if (pv && !compile_ascii_pattern_value(pv, n, err, errcap)) {
            schema_free(n);
            return NULL;
        }
        int lo = 0, hi = -1;
        if (!compile_bound(jv_get(m, "minLength"), 0, &lo) ||
            !compile_bound(jv_get(m, "maxLength"), -1, &hi)) {
            snprintf(err, errcap, "invalid string length bounds");
            schema_free(n);
            return NULL;
        }
        if (lo > n->min_items) n->min_items = lo;
        if (hi >= 0 && (n->max_items < 0 || hi < n->max_items)) n->max_items = hi;
        if (n->max_items >= 0 && n->min_items > n->max_items) {
            snprintf(err, errcap, "invalid string length bounds");
            schema_free(n);
            return NULL;
        }
    }
    if (n->n_pats > 1 && !patterns_consistent(n, err, errcap)) {
        schema_free(n);
        return NULL;
    }
    if (n->n_pats && pat_max_len(n) >= 0 &&
        n->min_items > pat_max_len(n)) {
        // a bounded pattern that can never be long enough for minLength is
        // an empty language: refuse it at compile time rather than let a
        // request wedge with no admissible byte
        snprintf(err, errcap, "pattern cannot satisfy minLength");
        schema_free(n);
        return NULL;
    }
    if (n->n_pats && n->max_items >= 0 &&
        pat_min_len(n) > n->max_items) {
        snprintf(err, errcap, "pattern cannot satisfy maxLength");
        schema_free(n);
        return NULL;
    }
    return n;
}

// An array: its item schema and its item-count bounds.
static snode *compile_array(jv *s, char *err, int errcap, int depth) {
    snode *n = sn_new(SN_ARR);
    if (!n) return NULL;
    n->items = compile_node(jv_get(s, "items"), err, errcap, depth + 1);
    if (!n->items) { schema_free(n); return NULL; }
    jv *mi = jv_get(s, "minItems"), *ma = jv_get(s, "maxItems");
    if (!compile_bound(mi, 0, &n->min_items) ||
        !compile_bound(ma, -1, &n->max_items) ||
        (n->max_items >= 0 && n->min_items > n->max_items)) {
        snprintf(err, errcap, "invalid array item bounds");
        schema_free(n);
        return NULL;
    }
    return n;
}

// An object: closed and empty, a typed map, open, or declared properties
// with their required keys.
static snode *compile_object(jv *s, char *err, int errcap, int depth) {
    if (!check_object_rules(s, err, errcap)) return NULL;
    jv *props = jv_get(s, "properties");
    jv *apv = jv_get(s, "additionalProperties");
    bool closed_empty = (!props || (props->type == J_OBJ && props->n == 0)) &&
                        apv && apv->type == J_BOOL && !apv->b;
    if (closed_empty) {
        // {"properties":{},"additionalProperties":false} declares an object
        // with no permitted keys, i.e. exactly `{}`. Compiling it to the
        // open machine would accept any object at all, which is the
        // opposite of what was asked for.
        snode *n = sn_new(SN_OBJ);
        if (!n) return NULL;
        return n;
    }
    bool no_declared = !props || (props->type == J_OBJ && props->n == 0);
    if (no_declared && apv && apv->type == J_OBJ && apv->n > 0) {
        // A schema-valued additionalProperties with no named properties
        // is a homogeneous string-keyed map. Keep its value schema exact;
        // compiling this as SN_ANY would silently discard the constraint.
        snode *n = sn_new(SN_MAP);
        if (!n) return NULL;
        n->items = compile_node(apv, err, errcap, depth + 1);
        if (!n->items) { schema_free(n); return NULL; }
        return n;
    }
    if (!props || props->type != J_OBJ || props->n == 0) {
        // open object: any JSON object (generic machine, '{' enforced)
        snode *n = sn_new(SN_ANY);
        if (!n) return NULL;
        n->min_items = 1; // flag: object-rooted generic value
        return n;
    }
    if (props->n > 60) {
        snprintf(err, errcap, "too many properties (max 60)");
        return NULL;
    }
    snode *n = sn_new(SN_OBJ);
    if (!n) return NULL;
    n->keys    = calloc(props->n, sizeof(char *));
    n->key_len = calloc(props->n, sizeof(int));
    n->props   = calloc(props->n, sizeof(snode *));
    n->req     = calloc(props->n, sizeof(bool));
    if (!n->keys || !n->key_len || !n->props || !n->req) { schema_free(n); return NULL; }
    n->n_props = props->n;   // only once the arrays schema_free walks exist
    for (int i = 0; i < props->n; i++) {
        if (!plain_key(props->keys[i])) {
            snprintf(err, errcap, "property keys needing JSON escapes are unsupported");
            schema_free(n);
            return NULL;
        }
        n->keys[i] = strdup(props->keys[i]);
        if (!n->keys[i]) { schema_free(n); return NULL; }
        n->key_len[i] = (int)strlen(props->keys[i]);
        n->props[i] = compile_node(props->items[i], err, errcap, depth + 1);
        if (!n->props[i]) { schema_free(n); return NULL; }
    }
    jv *req = jv_get(s, "required");
    if (req && req->type == J_ARR) {
        for (int r = 0; r < req->n; r++) {
            const char *k = jv_str(req->items[r], NULL);
            bool found = false;
            for (int i = 0; i < props->n && k; i++)
                if (!strcmp(n->keys[i], k)) { n->req[i] = true; found = true; }
            if (!found) {
                snprintf(err, errcap, "required key '%s' not in properties",
                         k ? k : "?");
                schema_free(n);
                return NULL;
            }
        }
    }
    return n;
}

static snode *compile_typed(jv *s, const char *type, char *err, int errcap, int depth) {
    if (!strcmp(type, "string")) return compile_string(s, err, errcap);
    if (!strcmp(type, "number")) {
        snode *n = sn_new(SN_NUM);
        if (!n) return NULL;
        if (!compile_number_bounds(s, n, err, errcap)) {
            schema_free(n);
            return NULL;
        }
        return n;
    }
    if (!strcmp(type, "integer")) {
        snode *n = sn_new(SN_INT);
        if (!n) return NULL;
        if (!compile_integer_bounds(s, n, err, errcap)) {
            schema_free(n);
            return NULL;
        }
        return n;
    }
    if (!strcmp(type, "boolean")) return sn_new(SN_BOOL);
    if (!strcmp(type, "null"))    return sn_new(SN_NULL);
    if (!strcmp(type, "array"))   return compile_array(s, err, errcap, depth);
    if (!strcmp(type, "object"))  return compile_object(s, err, errcap, depth);
    snprintf(err, errcap, "unsupported type '%s'", type);
    return NULL;
}

// first bytes that can start a value of node `a`; false when the node cannot
// be dispatched by first byte at all (nested unions/conditionals, open any)
static bool union_start_bytes(const snode *a, bool set[256]) {
    switch (a->kind) {
        case SN_STR: set['"'] = true; return true;
        case SN_ENUM:
            for (int i = 0; i < a->n_lits; i++)
                set[(uint8_t)a->lits[i][0]] = true;
            return true;
        case SN_OBJ: case SN_MAP: set['{'] = true; return true;
        case SN_ARR: set['['] = true; return true;
        case SN_BOOL: set['t'] = true; set['f'] = true; return true;
        case SN_NULL: set['n'] = true; return true;
        case SN_NUM: case SN_INT:
            set['-'] = true;
            for (int d = '0'; d <= '9'; d++) set[d] = true;
            return true;
        // A sequence starts wherever its first element does. Without the
        // recursion a SEQ of SEQ reported "no start bytes" and became an
        // unreachable union alternative -- which is how gemma4's native array
        // elements (`<|"|>` opener, itself a two-node SEQ) would have failed.
        case SN_SEQ:
            return a->n_props > 0 && union_start_bytes(a->props[0], set);
        case SN_MEMBERS:
            for (int i = 0; i < a->n_props; i++)
                set[(uint8_t)a->keys[i][0]] = true;
            if (a->sentinel_len) set[(uint8_t)a->sentinel[0]] = true;
            return true;
        // Raw text accepts ANY byte, so as a union alternative it is the
        // catch-all. Order matters and is the caller's: put it last.
        case SN_RAW:
            for (int i = 0; i < 256; i++) set[i] = true;
            return true;
        default: return false;
    }
}

static snode *compile_oneof(jv *alts, char *err, int errcap, int depth) {
    if (!alts || alts->type != J_ARR || alts->n <= 0) {
        snprintf(err, errcap, "oneOf/anyOf must be a non-empty array");
        return NULL;
    }
    bool all_scalar_const = true;
    for (int i = 0; i < alts->n; i++) {
        jv *cn = jv_get(alts->items[i], "const");
        if (!cn || (cn->type != J_STR && cn->type != J_NUM &&
                    cn->type != J_BOOL && cn->type != J_NULL)) {
            all_scalar_const = false;
            break;
        }
    }
    if (all_scalar_const && alts->n > SCHEMA_ENUM_MAX) {
        snprintf(err, errcap, "enum size must be 1..%d", SCHEMA_ENUM_MAX);
        return NULL;
    }
    bool matched = false;
    snode *disc = compile_discriminated_action(alts, err, errcap, depth, &matched);
    if (matched) return disc;

    snode *n = sn_new(SN_UNION);
    if (!n) return NULL;
    n->alts = calloc(alts->n, sizeof(snode *));
    if (!n->alts) { schema_free(n); return NULL; }
    for (int i = 0; i < alts->n; i++) {
        n->alts[n->n_alts] = compile_node(alts->items[i], err, errcap, depth + 1);
        if (!n->alts[n->n_alts]) { schema_free(n); return NULL; }
        n->n_alts++;
    }
    /* JSON-schema generators commonly spell a string enum plus one sentinel
       const as anyOf. They are one literal language, not an ambiguous union. */
    int literal_count = 0;
    bool all_literals = true;
    for (int i = 0; i < n->n_alts; i++) {
        if (n->alts[i]->kind != SN_ENUM) { all_literals = false; break; }
        literal_count += n->alts[i]->n_lits;
    }
    if (all_literals && literal_count > 0 && literal_count <= SCHEMA_ENUM_MAX) {
        snode *merged = sn_new(SN_ENUM);
        if (!merged) { schema_free(n); return NULL; }
        merged->lits = calloc((size_t)literal_count, sizeof(char *));
        if (!merged->lits) { schema_free(merged); schema_free(n); return NULL; }
        for (int i = 0; i < n->n_alts; i++) {
            snode *a = n->alts[i];
            for (int j = 0; j < a->n_lits; j++) {
                merged->lits[merged->n_lits++] = a->lits[j];
                a->lits[j] = NULL;
            }
        }
        if (!enum_index(merged)) { schema_free(merged); schema_free(n); return NULL; }
        schema_free(n);
        return merged;
    }
    // the validator dispatches a union on the first byte of the value —
    // alternatives it could never select must fail here, at request time,
    // not silently mis-constrain sampling later
    if (n->n_alts > 1) {
        bool seen[256] = { false };
        for (int i = 0; i < n->n_alts; i++) {
            bool mine[256] = { false };
            if (!union_start_bytes(n->alts[i], mine)) {
                snprintf(err, errcap,
                         "oneOf alternative %d cannot be dispatched by its first byte", i);
                schema_free(n);
                return NULL;
            }
            for (int b = 0; b < 256; b++) {
                if (mine[b] && seen[b]) {
                    snprintf(err, errcap,
                             "oneOf alternatives are ambiguous (share a starting byte)");
                    schema_free(n);
                    return NULL;
                }
                if (mine[b]) seen[b] = true;
            }
        }
    }
    return n;
}

// does scalar literal `v` satisfy the `type` keyword (a string or a list)?
static bool literal_has_type_name(const jv *v, const char *t) {
    if (!strcmp(t, "string"))  return v->type == J_STR;
    if (!strcmp(t, "boolean")) return v->type == J_BOOL;
    if (!strcmp(t, "null"))    return v->type == J_NULL;
    if (!strcmp(t, "number"))  return v->type == J_NUM;
    if (!strcmp(t, "integer")) return v->type == J_NUM && v->num == floor(v->num);
    return false; // object / array literals are refused as non-scalars anyway
}

static bool schema_type_name(const char *t) {
    return !strcmp(t, "string") || !strcmp(t, "number") ||
           !strcmp(t, "integer") || !strcmp(t, "boolean") ||
           !strcmp(t, "null") || !strcmp(t, "array") ||
           !strcmp(t, "object");
}

static bool literal_has_type(const jv *v, jv *ty) {
    if (ty->type == J_STR) return literal_has_type_name(v, ty->str);
    if (ty->type == J_ARR) {
        for (int i = 0; i < ty->n; i++)
            if (literal_has_type_name(v, jv_str(ty->items[i], "?"))) return true;
        return false;
    }
    return true; // a malformed type keyword is reported by compile_typed
}
static bool literal_equal(const jv *a, const jv *b) {
    if (a->type != b->type) return false;
    switch (a->type) {
        case J_NUM:  return a->num == b->num;
        case J_STR:  return !strcmp(a->str, b->str);
        case J_BOOL: return a->b == b->b;
        case J_NULL: return true;
        default:     return false;
    }
}

// The `type` keyword's own shape: a supported type name, or a non-empty
// array of them.
static bool check_type_keyword(jv *ty, char *err, int errcap) {
    if (ty && ty->type != J_STR && ty->type != J_ARR) {
        snprintf(err, errcap, "bad 'type' value");
        return false;
    }
    if (ty && ty->type == J_STR && !schema_type_name(ty->str)) {
        snprintf(err, errcap, "unsupported type '%s'", ty->str);
        return false;
    }
    if (ty && ty->type == J_ARR) {
        if (ty->n <= 0) {
            snprintf(err, errcap, "'type' array must list at least one type");
            return false;
        }
        for (int i = 0; i < ty->n; i++) {
            if (!ty->items[i] || ty->items[i]->type != J_STR) {
                snprintf(err, errcap, "'type' array members must be strings");
                return false;
            }
            if (!schema_type_name(ty->items[i]->str)) {
                snprintf(err, errcap, "unsupported type '%s'",
                         ty->items[i]->str);
                return false;
            }
        }
    }
    return true;
}

// enum / const: the literals that can validate under the declared type,
// in declared order.
static snode *compile_literals(jv *en, jv *cn, jv *ty, char *err, int errcap) {
    if (en && en->type != J_ARR) {
        // an object-valued enum was read as a list of its VALUES, so
        // {"enum":{"a":1}} compiled to the literal 1 -- a constraint the
        // caller never wrote
        snprintf(err, errcap, "enum must be an array");
        return NULL;
    }
    int cnt = en ? en->n : 1;
    if (cnt <= 0 || cnt > SCHEMA_ENUM_MAX) {
        snprintf(err, errcap, "enum size must be 1..%d", SCHEMA_ENUM_MAX);
        return NULL;
    }
    for (int i = 0; i < cnt; i++) {
        jv *v = en ? en->items[i] : cn;
        if (v->type != J_STR && v->type != J_NUM &&
            v->type != J_BOOL && v->type != J_NULL) {
            snprintf(err, errcap, "enum values must be scalars");
            return NULL;
        }
    }
    // Siblings intersect, they do not lose: an enum value outside the
    // declared type is dropped (it could never validate), and a const
    // beside an enum must be one of its members. Before this,
    // {"type":"integer","enum":["bad",1]} accepted "bad" and
    // {"const":1,"enum":[2]} accepted 2.
    jv **keep = malloc(sizeof(jv *) * (size_t)cnt);   // cnt <= SCHEMA_ENUM_MAX
    if (!keep) return NULL;
    int n_keep = 0;
    for (int i = 0; i < cnt; i++) {
        jv *v = en ? en->items[i] : cn;
        if (ty && !literal_has_type(v, ty)) continue;
        if (en && cn && !literal_equal(v, cn)) continue;
        keep[n_keep++] = v;
    }
    if (n_keep == 0) {
        snprintf(err, errcap, en && cn
                 ? "const is not one of the enum values"
                 : "no enum value matches the declared type");
        free(keep);
        return NULL;
    }
    snode *n = sn_new(SN_ENUM);
    if (!n) { free(keep); return NULL; }
    n->lits = calloc(n_keep, sizeof(char *));
    if (!n->lits) { schema_free(n); free(keep); return NULL; }
    for (int i = 0; i < n_keep; i++) {
        char *lit = sn_literal(keep[i]);
        if (!lit) { schema_free(n); free(keep); return NULL; }
        n->lits[i] = lit;
        n->n_lits++;
    }
    free(keep);
    if (!enum_index(n)) { schema_free(n); return NULL; }
    return n;
}

// A `type` array, e.g. ["string","null"]: one alternative per type.
static snode *compile_type_union(jv *s, jv *ty, char *err, int errcap, int depth) {
    snode *n = sn_new(SN_UNION);
    if (!n) return NULL;
    n->alts = calloc(ty->n, sizeof(snode *));
    if (!n->alts) { schema_free(n); return NULL; }
    // number|integer merge into one numeric alternative; it is "number"
    // only when "number" is actually listed. ["integer","null"] used to
    // widen to number because the list had more than one member, so
    // 1.5 validated as an integer.
    bool any_number = false;
    for (int i = 0; i < ty->n; i++)
        if (!strcmp(jv_str(ty->items[i], "?"), "number")) any_number = true;
    bool has_num = false;
    for (int i = 0; i < ty->n; i++) {
        const char *t = jv_str(ty->items[i], "?");
        if ((!strcmp(t, "number") || !strcmp(t, "integer"))) {
            if (has_num) continue; // merge number|integer
            has_num = true;
            t = any_number ? "number" : "integer";
        }
        snode *alt = compile_typed(s, t, err, errcap, depth + 1);
        if (!alt) { schema_free(n); return NULL; }
        n->alts[n->n_alts++] = alt;
    }
    return n;
}

snode *compile_node(jv *s, char *err, int errcap, int depth) {
    if (depth > 24) { snprintf(err, errcap, "schema too deep"); return NULL; }
    if (s && s->type == J_BOOL && !s->b) {
        // `false` admits no value at all. It used to compile to ANY, the
        // exact opposite, so {"properties":{"x":false},"required":["x"]}
        // accepted {"x":42}. Refused rather than weakened.
        snprintf(err, errcap, "boolean schema false admits no value");
        return NULL;
    }
    if (!s || (s->type == J_OBJ && s->n == 0) ||
        s->type == J_BOOL) // absent / `true` / `{}` = anything
        return sn_new(SN_ANY);
    if (s->type != J_OBJ) { snprintf(err, errcap, "schema node must be an object"); return NULL; }
    if (!check_keywords(s, err, errcap)) return NULL;

    jv *one = jv_get(s, "oneOf");
    jv *any = jv_get(s, "anyOf");
    jv *ty = jv_get(s, "type");
    if ((one || any) && ty) {
        // a sibling `type` must hold for every alternative; it was dropped,
        // so {"type":"string","anyOf":[...,{"type":"integer"}]} accepted 1
        snprintf(err, errcap, "'type' beside oneOf/anyOf is not supported: "
                 "declare the type on each alternative");
        return NULL;
    }
    if (one || any) return compile_oneof(one ? one : any, err, errcap, depth);

    // enum/const return before compile_typed, so validate the type keyword's
    // shape here rather than relying on the typed path to catch it later.
    if (!check_type_keyword(ty, err, errcap)) return NULL;

    // enum / const dominate the type
    jv *en = jv_get(s, "enum");
    jv *cn = jv_get(s, "const");
    if (en || cn) return compile_literals(en, cn, ty, err, errcap);

    if (!ty) {
        if (jv_get(s, "properties")) return compile_typed(s, "object", err, errcap, depth);
        if (jv_get(s, "items"))      return compile_typed(s, "array", err, errcap, depth);
        return sn_new(SN_ANY);
    }
    if (ty->type == J_STR) return compile_typed(s, ty->str, err, errcap, depth);
    if (ty->type == J_ARR) return compile_type_union(s, ty, err, errcap, depth);
    snprintf(err, errcap, "bad 'type' value");
    return NULL;
}

snode *schema_compile(struct jv *schema, char *err, int errcap) {
    err[0] = 0;
    snode *n = compile_node(schema, err, errcap, 0);
    // An allocation failure unwinds as a bare NULL from wherever it happened,
    // so the one message it cannot carry is filled in here. Callers print this
    // string; leaving it empty would report a rejected schema with no reason.
    if (!n && err[0] == 0)
        snprintf(err, errcap, "out of memory compiling schema");
    return n;
}

// ---------------------------------------------------------------- validate

// frame phases
enum {
    P_START,          // value not begun
    P_OBJ_KEY1,       // after '{': key or '}'
    P_OBJ_KEY,        // after ',': key
    P_OBJ_INKEY,      // inside key string
    P_OBJ_COLON,
    P_OBJ_NEXT,       // after value: ',' or '}'
    P_ARR_FIRST,      // after '[': value or ']'
    P_ARR_NEXT,       // after item: ',' or ']'
    P_STR,            // inside string
    P_LIT,            // enum / bool / null literal
    P_NUM,
    P_SEQ,
    P_RAW,
    P_MEM_FIRST,      // native members: before the first emitted member
    P_MEM_NEXT,       // native members: after one emitted member
};

// number micro-states (frame->sub)
enum { N_START, N_MINUS, N_ZERO, N_INT, N_FRAC0, N_FRAC, N_EXP0, N_EXP1, N_EXP };

static int raw_prefix(const char *marker, int pos, uint8_t c) {
    if ((uint8_t)marker[pos]==c) return pos+1;
    int k=pos;
    while (k>0 && !(marker[k-1]==(char)c &&
           !memcmp(marker,marker+pos+1-k,(size_t)(k-1)))) k--;
    return k;
}

static bool is_ws(uint8_t c) {
    return c == ' ' || c == '\t' || c == '\n' || c == '\r';
}

void sval_init(sval *v, const snode *root) {
    memset(v, 0, sizeof(*v));
    v->stack[0] = (sframe){ .node = root, .phase = P_START };
    v->depth = 1;
    v->last_enum = -1;
}

// discriminator choice for the frame at stack index `at`: an SN_COND frame
// reads its owning object (the frame below), everything else its own record
static int frame_choice(const sval *v, int at) {
    const sframe *f = &v->stack[at];
    if (f->node->kind == SN_COND)
        return at > 0 ? (int)v->stack[at - 1].disc - 1 : -1;
    return (int)f->disc - 1;
}

// key candidates from prop index `from`: every prop until (and including)
// the first required one may come next
static uint64_t key_candidates(const snode *n, int from) {
    uint64_t m = 0;
    for (int i = from; i < n->n_props; i++) {
        m |= 1ull << i;
        if (n->req[i]) break;
    }
    return m;
}

static bool close_allowed(const snode *n, int from) {
    for (int i = from; i < n->n_props; i++)
        if (n->req[i]) return false;
    return true;
}

// Native ordered members use one extra candidate bit for the closing literal.
// A close is reachable only when no required member remains, exactly as for a
// JSON object; already-consumed members lie below `from`, so duplicates and
// backwards order are unreachable by construction.
static uint64_t member_candidates(const snode *n, int from) {
    uint64_t m = key_candidates(n, from);
    if (close_allowed(n, from)) m |= 1ull << n->n_props;
    return m;
}

static const char *member_prefix(const snode *n, int which, bool first) {
    if (which == n->n_props) return n->sentinel;
    return first ? n->keys[which] : n->next_keys[which];
}

static int member_prefix_len(const snode *n, int which, bool first) {
    if (which == n->n_props) return n->sentinel_len;
    return first ? n->key_len[which] : n->next_key_len[which];
}

static void frame_done(sval *v);

// child value finished: advance parent
static void frame_done(sval *v) {
    const snode *child = v->stack[v->depth - 1].node;
    if (child->kind == SN_MAP && v->n_seen) {
        // this map's keys leave the guard with it; a sibling map that opens
        // later at the same depth starts clean
        int w = 0;
        for (int i = 0; i < v->n_seen; i++)
            if (v->seen_depth[i] != v->depth) {
                v->seen_hash[w] = v->seen_hash[i];
                v->seen_depth[w] = v->seen_depth[i];
                w++;
            }
        v->n_seen = (uint8_t)w;
    }
    v->depth--;
    if (v->depth == 0) { v->done = true; return; }
    sframe *f = &v->stack[v->depth - 1];
    if (f->node->kind == SN_OBJ || f->node->kind == SN_MAP) {
        if (f->sub < f->node->n_props && v->last_enum >= 0 &&
            !strcmp(f->node->keys[f->sub], "tool"))
            f->disc = (uint16_t)(v->last_enum + 1);
        f->phase = P_OBJ_NEXT;
    } else if (f->node->kind == SN_SEQ) {
        if (child->kind == SN_ENUM && child->min_items && v->last_enum >= 0)
            f->disc = (uint16_t)(v->last_enum + 1);
        if (f->idx >= f->node->n_props) frame_done(v);
        else f->phase = P_SEQ;
    } else if (f->node->kind == SN_MEMBERS) {
        f->phase = P_MEM_NEXT;
        f->alive = 0;
        f->lit_pos = 0;
        f->sub = 0;
    } else {
        f->phase = P_ARR_NEXT; // SN_ARR
    }
}

// begin a value of type `n` on top of the stack (replaces union in place)
static bool push_value(sval *v, const snode *n) {
    if (v->depth >= (int)(sizeof(v->stack) / sizeof(v->stack[0]))) return false;
    v->last_enum = -1;
    v->stack[v->depth++] = (sframe){ .node = n, .phase = P_START };
    return true;
}

// which union alternative starts with byte c?
static const snode *pick_alt(const snode *u, uint8_t c) {
    for (int i = 0; i < u->n_alts; i++) {
        const snode *a = u->alts[i];
        switch (a->kind) {
            case SN_STR:  if (c == '"') return a; break;
            case SN_ENUM:
                for (int j = 0; j < a->n_lits; j++)
                    if (c == a->lits[j][0]) return a;
                break;
            case SN_OBJ: case SN_MAP: if (c == '{') return a; break;
            case SN_ARR:  if (c == '[') return a; break;
            case SN_SEQ:
                if (a->n_props > 0) {
                    bool starts[256] = {0};
                    if (union_start_bytes(a->props[0], starts) && starts[c])
                        return a;
                }
                break;
            case SN_MEMBERS:
                for (int j = 0; j < a->n_props; j++)
                    if (c == (uint8_t)a->keys[j][0]) return a;
                if (a->sentinel_len && c == (uint8_t)a->sentinel[0]) return a;
                break;
            case SN_BOOL: if (c == 't' || c == 'f') return a; break;
            case SN_NULL: if (c == 'n') return a; break;
            case SN_NUM: case SN_INT:
                if (c == '-' || (c >= '0' && c <= '9')) return a;
                break;
            // The generic machine holds any value, which makes it the union's
            // catch-all -- but an OBJECT-rooted one (compile_typed's open
            // object) only ever starts at '{'. Dispatching every byte to it
            // made every later alternative unreachable, so
            // `{"type":["object","null"]}` refused `null`.
            case SN_ANY:  if (a->min_items && c != '{') break; return a;
            case SN_RAW:  return a;   // catch-all; see union_start_bytes
            default: break;
        }
    }
    return NULL;
}

// string content byte (frame->sub/esc track escapes, with the pairing rules
// shared with json_mode -- see json_escape_hex); returns -1 invalid,
// 0 continue, 1 string closed
static int str_byte(uint8_t c, uint8_t *sub, uint16_t *esc,
                    uint8_t *utf8_state) {
    if (*sub == 1) { // after backslash
        if (c == '"' || c == '\\' || c == '/' || c == 'b' || c == 'f' ||
            c == 'n' || c == 'r' || c == 't') { *sub = 0; return 0; }
        if (c == 'u') { *sub = 2; return 0; }
        return -1;
    }
    if (*sub == 6) { if (c != '\\') return -1; *sub = 7; return 0; }
    if (*sub == 7) { if (c != 'u')  return -1; *sub = 8; return 0; }
    if (*sub >= 2) return json_escape_hex(sub, esc, c) ? 0 : -1;
    if (*utf8_state) return json_utf8_byte(utf8_state, c) ? 0 : -1;
    if (c == '"') return 1;
    if (c == '\\') { *sub = 1; return 0; }
    if (c < 0x20) return -1;
    return json_utf8_byte(utf8_state, c) ? 0 : -1;
}

// number byte; returns -1 invalid, 0 consumed, 1 complete-and-reconsume
static int num_byte(uint8_t c, uint8_t *st, bool integer) {
    switch (*st) {
        case N_START:
            if (c == '-') { *st = N_MINUS; return 0; }
            if (c == '0') { *st = N_ZERO; return 0; }
            if (c >= '1' && c <= '9') { *st = N_INT; return 0; }
            return -1;
        case N_MINUS:
            if (c == '0') { *st = N_ZERO; return 0; }
            if (c >= '1' && c <= '9') { *st = N_INT; return 0; }
            return -1;
        case N_ZERO:
        case N_INT:
            if (*st == N_INT && c >= '0' && c <= '9') return 0;
            if (!integer && c == '.') { *st = N_FRAC0; return 0; }
            if (!integer && (c == 'e' || c == 'E')) { *st = N_EXP0; return 0; }
            return 1;
        case N_FRAC0:
            if (c >= '0' && c <= '9') { *st = N_FRAC; return 0; }
            return -1;
        case N_FRAC:
            if (c >= '0' && c <= '9') return 0;
            if (c == 'e' || c == 'E') { *st = N_EXP0; return 0; }
            return 1;
        case N_EXP0:
            if (c == '+' || c == '-') { *st = N_EXP1; return 0; }
            if (c >= '0' && c <= '9') { *st = N_EXP; return 0; }
            return -1;
        case N_EXP1:
            if (c >= '0' && c <= '9') { *st = N_EXP; return 0; }
            return -1;
        case N_EXP:
            if (c >= '0' && c <= '9') return 0;
            return 1;
    }
    return -1;
}

static bool num_complete(uint8_t st) {
    return st == N_ZERO || st == N_INT || st == N_FRAC || st == N_EXP;
}

// The spelling buffer lives in the sval, not the frame: only the top frame
// can be inside a number (a number frame never pushes a child), so one buffer
// serves the whole stack.
static bool number_put(sval *v, uint8_t c) {
    if ((size_t)v->num_len + 1 >= sizeof(v->num_text)) return false;
    v->num_text[v->num_len++] = (char)c;
    v->num_text[v->num_len] = 0;
    return true;
}

// Does this complete number SPELLING satisfy the node's interval? Taken as
// text rather than as an accumulated value so the closer can ask the same
// question about a spelling it is only considering. Parseability comes from
// json_number_text_ok — the parser's own acceptance, ERANGE included — so a
// spelling json_parse refuses (overflow OR underflow) never satisfies any
// bound. The old isfinite() check here was dead code in the shipped build
// (-ffast-math folds it away) and never caught underflow at all.
static bool number_text_in_bounds(const snode *n, const char *s) {
    double x;
    if (!json_number_text_ok(s, &x)) return false;
    return (!n->has_real_min || x >= n->real_min) &&
           (!n->has_real_max || x <= n->real_max);
}

static bool number_in_bounds(const sval *v, const snode *n, const sframe *f) {
    if (!num_complete(f->sub) || !v->num_len) return false;
    return number_text_in_bounds(n, v->num_text);
}

static bool integer_value(const sframe *f, int64_t *out) {
    if (!num_complete(f->sub) || f->sub == N_FRAC || f->sub == N_EXP) return false;
    if (f->num_abs > (uint64_t)JSON_SAFE_INTEGER) return false;
    // The sign is retained in lit_pos: -1 after a leading minus, +1 otherwise.
    bool neg = f->lit_pos < 0;
    *out = neg ? -(int64_t)f->num_abs : (int64_t)f->num_abs;
    return true;
}

static bool integer_in_bounds(const snode *n, const sframe *f) {
    int64_t v;
    if (!integer_value(f, &v)) return false;
    return (!n->has_num_min || v >= n->num_min) &&
           (!n->has_num_max || v <= n->num_max);
}

static bool ranges_intersect(int64_t lo, int64_t hi, int64_t want_lo,
                             int64_t want_hi) {
    return lo <= want_hi && hi >= want_lo;
}

// Is the integer prefix still capable of becoming a value in the interval?
// This is what lets constrained sampling reject `56` for maximum 55 before
// the model commits to a prefix no delimiter could make valid.
static bool integer_prefix_viable(const snode *n, const sframe *f) {
    if (!n->has_num_min && !n->has_num_max) return true;
    int64_t want_lo = n->has_num_min ? n->num_min : -JSON_SAFE_INTEGER;
    int64_t want_hi = n->has_num_max ? n->num_max :  JSON_SAFE_INTEGER;
    bool neg = f->lit_pos < 0;
    uint64_t p = f->num_abs;
    if (p > (uint64_t)JSON_SAFE_INTEGER) return false;
    if (f->sub == N_ZERO) {
        int64_t v = neg ? 0 : (int64_t)p;
        return v >= want_lo && v <= want_hi;
    }
    uint64_t scale = 1;
    for (;;) {
        uint64_t low_abs = p * scale;
        uint64_t high_abs = low_abs + scale - 1;
        if (high_abs > (uint64_t)JSON_SAFE_INTEGER)
            high_abs = (uint64_t)JSON_SAFE_INTEGER;
        int64_t lo = neg ? -(int64_t)high_abs : (int64_t)low_abs;
        int64_t hi = neg ? -(int64_t)low_abs  : (int64_t)high_abs;
        if (ranges_intersect(lo, hi, want_lo, want_hi)) return true;
        if (scale > (uint64_t)JSON_SAFE_INTEGER / 10 ||
            p > (uint64_t)JSON_SAFE_INTEGER / (scale * 10))
            break;
        scale *= 10;
    }
    return false;
}

// Same tri-state as num_byte, and it is the same verdict: -1 invalid,
// 0 consumed, 1 the integer is complete and `c` belongs to the parent. The
// completion signal has to travel out of here rather than be re-derived by the
// caller, because num_byte ends an integer at `0` followed by ANY byte (RFC
// 8259 forbids `01`) while the caller could only ask whether the byte looked
// like a terminator. A digit does not, so `01` was consumed silently: the
// document went out as JSON no reader accepts, and f->num_abs stayed at 0, so
// every bound was satisfied by a value the model never wrote.
static int integer_take_byte(const snode *n, sframe *f, uint8_t c) {
    uint8_t before = f->sub;
    int r = num_byte(c, &f->sub, true);
    if (r != 0) return (r > 0 && integer_in_bounds(n, f)) ? 1 : -1;
    if (before == N_START && c == '-') {
        f->lit_pos = -1;
        return (!n->has_num_min || n->num_min < 0) ? 0 : -1;
    }
    if (c >= '0' && c <= '9') {
        if (f->num_abs > (uint64_t)JSON_SAFE_INTEGER / 10) return -1;
        f->num_abs = f->num_abs * 10 + (uint64_t)(c - '0');
        if (f->num_abs > (uint64_t)JSON_SAFE_INTEGER) return -1;
        if (f->lit_pos == 0) f->lit_pos = 1;
        return integer_prefix_viable(n, f) ? 0 : -1;
    }
    return 0;
}

// A constrained document must begin with its opening token: whitespace before
// the root value opens is refused (-1), whitespace before any nested value is
// consumed as usual (0).
//
// Leading whitespace is where constrained decode livelocks. A model that
// would rather emit a preamble has every prose token rejected, leaving spaces
// and newlines as the only legal continuations — so it emits those until the
// budget is gone and never reaches the opening brace. The result used to be a
// force-closed document with empty values that parsed cleanly, so no caller
// could tell. Refusing the very first whitespace byte costs a well-behaved
// model nothing (there is always a token starting with the opening character)
// and denies the livelock its fuel.
//
// The ban stops at the root. Interior whitespace is how models pretty-print —
// `{ "a" : "b" }` is Llama-3.2's ordinary output — and bounding it there would
// break well-behaved models for no gain, since by then the document has real
// content in it.
static int leading_ws_ok(const sval *v) {
    return v->depth > 1 ? 0 : -1;
}

// feed one byte; returns -1 invalid, 0 consumed, 1 reconsume (frame popped)
static int feed_byte(sval *v, uint8_t c) {
    if (v->done) return -1; // nothing after the root value
    sframe *f = &v->stack[v->depth - 1];
    const snode *n = f->node;

    // generic any-value subtree
    if (n->kind == SN_ANY) {
        if (f->phase == P_START) {
            if (is_ws(c)) return leading_ws_ok(v);
            // v->depth over-estimates the containers open above (a number
            // or string frame is not a container), which is the fail-closed
            // direction: the submachine gets a budget no larger than what is
            // actually left, never larger.
            jsonv_init_nested(&v->any, n->min_items != 0, v->depth);
            f->phase = P_STR; // "running"
        }
        if (v->any.done) { frame_done(v); return 1; }
        // Numbers inside the free subtree flow through the generic machine,
        // which never buffers a spelling — so mirror it into num_text (free
        // here: no number frame can be open while an SN_ANY frame runs) and
        // apply the P_NUM rules at the same commit points: refuse the
        // exponent digit whose value json_parse refuses, and cap the
        // spelling at num_text's size the way number_put does. Terminators
        // stay legal in both cases.
        int num_st = jsonv_number_state(&v->any);
        bool num_ch = (c >= '0' && c <= '9') || c == '.' || c == '+' ||
                      c == '-' || c == 'e' || c == 'E';
        if (num_st && num_ch) {
            if ((size_t)v->num_len + 1 >= sizeof(v->num_text)) return -1;
            if (num_st == 2 && c >= '0' && c <= '9') {
                char cand[sizeof(v->num_text) + 1];
                memcpy(cand, v->num_text, v->num_len);
                cand[v->num_len] = (char)c;
                cand[v->num_len + 1] = 0;
                if (!json_number_text_ok(cand, NULL)) return -1;
            }
        }
        if (jsonv_feed(&v->any, (const char *)&c, 1)) {
            if (jsonv_number_state(&v->any)) {
                if (!num_st) v->num_len = 0;   // a number starts on this byte
                (void)number_put(v, c);        // cap enforced above
            }
            if (v->any.done) frame_done(v);
            return 0;
        }
        // invalid for the submachine: if it stopped at a self-terminating
        // value end (number at top level), the byte belongs to our parent
        if (jsonv_value_end(&v->any)) { frame_done(v); return 1; }
        return -1;
    }

    switch (f->phase) {
    case P_START:
            if (is_ws(c) && !n->whitespace_significant)
            return leading_ws_ok(v);
        switch (n->kind) {
        case SN_COND: {
            int choice = frame_choice(v, v->depth - 1);
            if (choice < 0 || choice >= n->n_alts) return -1;
            v->stack[v->depth - 1].node = n->alts[choice];
            return feed_byte(v, c);
        }
        case SN_UNION: {
            const snode *alt = pick_alt(n, c);
            if (!alt) return -1;
            v->stack[v->depth - 1].node = alt; // resolve in place
            return feed_byte(v, c);
        }
        case SN_STR:
            if (c != '"') return -1;
            f->phase = P_STR; f->sub = 0; f->lit_pos = 0;
            return 0;
        case SN_ENUM:
        case SN_BOOL:
        case SN_NULL:
            f->phase = P_LIT;
            f->lit_pos = 0;
            f->sub = 0;
            if (n->kind == SN_ENUM) {
                // a builder that filled the literals without indexing them
                // (the node is the grammar's own, mutable in fact)
                if (!n->order && !enum_index((snode *)n)) return -1;
                // the live candidates of an enum are a RANGE of its sorted
                // literals (enum_index), packed lo | hi << 32; every literal
                // is live at the start, none has completed (idx 0)
                f->alive = (uint64_t)(uint32_t)n->n_lits << 32;
                f->idx = 0;
            } else {
                f->alive = n->kind == SN_BOOL ? 3 : 1; // true/false or null
            }
            return feed_byte(v, c) == -1 ? -1 : 0;
        case SN_NUM:
        case SN_INT:
            f->phase = P_NUM; f->sub = N_START; f->lit_pos = 0; f->num_abs = 0;
            v->num_len = 0;
            // opening byte: num_byte cannot report completion out of N_START,
            // so this is only ever "accepted" or "rejected"
            if (n->kind == SN_INT) return integer_take_byte(n, f, c) < 0 ? -1 : 0;
            // a minus under a non-negative minimum is a dead prefix: no
            // suffix can ever satisfy the bound, and the only exit would be
            // an all-tokens-masked stall — reject it up front (the integer
            // path already does)
            if (c == '-' && n->has_real_min && n->real_min >= 0) return -1;
            if (num_byte(c, &f->sub, false) != 0 || !number_put(v, c)) return -1;
            return 0;
        case SN_OBJ:
        case SN_MAP:
            if (c != '{') return -1;
            f->phase = P_OBJ_KEY1; f->idx = 0;
            return 0;
        case SN_ARR:
            if (c != '[') return -1;
            f->phase = P_ARR_FIRST; f->idx = 0;
            return 0;
        case SN_SEQ:
            if (n->n_props <= 0) { frame_done(v); return 1; }
            f->phase = P_SEQ;
            f->idx = 1;
            if (!push_value(v, n->props[0])) return -1;
            return feed_byte(v, c);
        case SN_MEMBERS:
            f->phase = P_MEM_FIRST;
            f->idx = 0;
            f->lit_pos = 0;
            f->sub = 0;
            f->alive = member_candidates(n, 0);
            return feed_byte(v, c);
        case SN_RAW:
            f->phase = P_RAW;
            f->lit_pos = 0;
            return feed_byte(v, c);
        default:
            return -1;
        }

    case P_STR: {
        if (n->n_pats && f->sub == 0 && c != '"') {
            if (c == '\\') return -1;
            // a character starts here: ASCII, or the lead byte of a UTF-8
            // sequence; its continuation bytes ride on utf8_state below and
            // occupy no pattern position, as the declared regex counts them
            if (f->utf8_state == 0) {
                pat_at at = pat_at_pos(n, f->lit_pos);
                if (at.what == PAT_LIT) {
                    if (c != at.lit) return -1;
                } else if (at.what == PAT_CLASS) {
                    if (c >= 128 ? !at.non_ascii : !at.ascii[c]) return -1;
                } else {
                    return -1;   // the patterns are complete: only the close quote
                }
            }
        }
        // a full string at maxLength admits only the closing quote — reject an
        // escape opener up front so a close() can never overrun the bound
        if (f->sub == 0 && c == '\\' &&
            n->max_items >= 0 && f->lit_pos >= n->max_items)
            return -1;
        bool continuing_utf8 = f->utf8_state != 0;
        int r = str_byte(c, &f->sub, &f->esc, &f->utf8_state);
        if (r < 0) return -1;
        if (r == 1) {
            if (f->lit_pos < n->min_items ||
                (n->n_pats && f->lit_pos < pat_min_len(n)) ||
                (n->max_items >= 0 && f->lit_pos > n->max_items))
                return -1;
            frame_done(v);
        } else if (f->sub == 0 && !continuing_utf8) {
            f->lit_pos++;
            if (n->max_items >= 0 && f->lit_pos > n->max_items)
                return -1;
        }
        return 0;
    }

    case P_LIT: {
        if (n->kind == SN_ENUM) {
            // The literals whose prefix matches the bytes so far are one
            // contiguous run of the sorted order, and a literal that ends
            // here sorts first in that run (a prefix sorts before what
            // extends it). So the frame carries a range, not a bit per
            // literal, and an enum can be as long as a function has lines.
            int lo = (int)(uint32_t)f->alive, hi = (int)(f->alive >> 32);
            int completed = -1, nlo = -1, nhi = -1;
            bool in_run = false;
            for (int k = lo; k < hi; k++) {
                const char *L = n->lits[n->order[k]];
                if (L[f->lit_pos] != (char)c) { if (in_run) break; continue; }
                in_run = true;
                if (L[f->lit_pos + 1] == 0) { completed = n->order[k]; continue; }
                if (nlo < 0) nlo = k;
                nhi = k + 1;
            }
            int pending_completed = f->idx > 0 ? f->idx - 1 : -1;
            if (completed >= 0 && nlo < 0) {
                v->last_enum = completed;
                frame_done(v);
                return 0;
            }
            if (nlo < 0) {
                if (pending_completed >= 0) {
                    v->last_enum = pending_completed;
                    frame_done(v);
                    return 1;
                }
                return -1;
            }
            f->alive = (uint64_t)(uint32_t)nlo | ((uint64_t)(uint32_t)nhi << 32);
            f->idx = completed >= 0 ? completed + 1 : 0;
            f->lit_pos++;
            return 0;
        }
        // bool / null: two literals or one, as a mask
        static const char *bools[] = { "true", "false" };
        static const char *nulls[] = { "null" };
        const char *const *lits = n->kind == SN_BOOL ? bools : nulls;
        int cnt = n->kind == SN_BOOL ? 2 : 1;
        uint64_t next = 0;
        int completed = -1;
        int pending_completed = f->sub ? f->sub - 1 : -1;
        for (int i = 0; i < cnt; i++) {
            if (!(f->alive & (1ull << i))) continue;
            const char *L = lits[i];
            if (L[f->lit_pos] != (char)c) continue;
            if (L[f->lit_pos + 1] == 0) completed = i;
            else next |= 1ull << i;
        }
        if (completed >= 0 && next == 0) {
            if (n->kind == SN_ENUM) v->last_enum = completed;
            frame_done(v);
            return 0;
        }
        if (!next) {
            if (pending_completed >= 0) {
                if (n->kind == SN_ENUM) v->last_enum = pending_completed;
                frame_done(v);
                return 1;
            }
            return -1;
        }
        f->alive = next;
        f->sub = completed >= 0 ? (uint8_t)(completed + 1) : 0;
        f->lit_pos++;
        return 0;
    }

    case P_NUM: {
        if (n->kind == SN_INT) {
            int r = integer_take_byte(n, f, c);
            if (r < 0) return -1;
            if (r > 0) { frame_done(v); return 1; }
            return 0;
        }
        int r = num_byte(c, &f->sub, false);
        if (r < 0) return -1;
        if (r == 1) {
            if (!number_in_bounds(v, n, f)) return -1;
            frame_done(v); return 1;
        }
        // An exponent digit that commits the spelling to a value json_parse
        // refuses (ERANGE, either direction) is refused HERE, not at the
        // terminator: json_escape_hex's principle — reject at the byte that
        // commits, so terminating the number always stays legal. Every
        // spelling that survives this can therefore be read back, which is
        // also what makes the closer's keep-the-prefix fallback sound.
        if (f->sub == N_EXP && c >= '0' && c <= '9') {
            char cand[sizeof(v->num_text) + 1];
            memcpy(cand, v->num_text, v->num_len);
            cand[v->num_len] = (char)c;
            cand[v->num_len + 1] = 0;
            if (!json_number_text_ok(cand, NULL)) return -1;
        }
        if (!number_put(v, c)) return -1;
        return 0;
    }

    case P_OBJ_KEY1:
    case P_OBJ_KEY:
        if (is_ws(c)) return 0;
        if (c == '}' && f->phase == P_OBJ_KEY1) {
            if (n->kind == SN_OBJ && !close_allowed(n, f->idx)) return -1;
            frame_done(v);
            return 0;
        }
        if (c != '"') return -1;
        if (n->kind == SN_MAP) {
            // FAIL CLOSED at guard capacity: this is P_OBJ_KEY1 whenever the
            // guard can be full (the comma path above refuses first), and
            // `}` is legal at KEY1, so refusing the key keeps a closeable
            // empty map instead of an untracked key
            if (v->n_seen >= MAP_SEEN_MAX) return -1;
            f->sub = 0;
            f->lit_pos = 0;
            f->num_abs = json_key_hash_init(); // see sframe.num_abs
            f->phase = P_OBJ_INKEY;
            return 0;
        }
        f->alive = key_candidates(n, f->idx);
        if (!f->alive) return -1;
        f->phase = P_OBJ_INKEY;
        f->lit_pos = 0;
        return 0;

    case P_OBJ_INKEY: {
        if (n->kind == SN_MAP) {
            bool continuing_utf8 = f->utf8_state != 0;
            uint8_t pre_sub = f->sub;
            int r = str_byte(c, &f->sub, &f->esc, &f->utf8_state);
            if (r < 0) return -1;
            if (r == 1) {
                // A key this map already has is refused AT ITS CLOSING
                // QUOTE: the model still holds every legal continuation
                // (extend the key, pick another), it just cannot finish a
                // duplicate -- which its own parser would refuse later
                // anyway. See map_seen in schema.h for the guard's scope.
                uint32_t kh = (uint32_t)f->num_abs;
                for (int i = 0; i < v->n_seen; i++)
                    if (v->seen_depth[i] == v->depth &&
                        v->seen_hash[i] == kh)
                        return -1;
                if (v->n_seen < MAP_SEEN_MAX) {
                    v->seen_hash[v->n_seen] = kh;
                    v->seen_depth[v->n_seen] = (uint8_t)v->depth;
                    v->n_seen++;
                }
                f->phase = P_OBJ_COLON;
            } else {
                // The guard hashes DECODED key content — raw bytes as
                // themselves, escapes as the scalar they decode to — so
                // `"a"` and `"a"` collide exactly as they do after
                // json_parse unescapes them. The low 32 bits of num_abs
                // hold the running hash; bits 32..47 stash a pending high
                // surrogate until its low half completes the pair.
                uint32_t kh = (uint32_t)f->num_abs;
                uint64_t hi_bits = f->num_abs & 0xFFFFFFFF00000000ull;
                if (pre_sub == 1) {
                    if (c != 'u')       // '\u' contributes nothing until its
                                        // digits complete a scalar below
                        kh = json_key_hash_byte(kh,
                                                json_escape_decode_simple(c));
                } else if (pre_sub >= 2) {
                    if (pre_sub <= 5 && f->sub == 6)
                        hi_bits = (uint64_t)f->esc << 32;
                    else if (pre_sub <= 5 && f->sub == 0)
                        kh = json_key_hash_scalar(kh, f->esc);
                    else if (pre_sub >= 8 && f->sub == 0) {
                        uint32_t hi = (uint32_t)((f->num_abs >> 32) & 0xFFFF);
                        kh = json_key_hash_scalar(kh,
                            0x10000u + ((hi - 0xD800u) << 10)
                                     + ((uint32_t)f->esc - 0xDC00u));
                    }
                } else if (!(pre_sub == 0 && c == '\\')) {
                    kh = json_key_hash_byte(kh, c);
                }
                f->num_abs = hi_bits | kh;
                if (f->sub == 0 && !continuing_utf8) f->lit_pos++;
            }
            return 0;
        }
        if (c == '"') {
            // exactly one candidate must match to full length
            for (int i = 0; i < n->n_props; i++) {
                if ((f->alive & (1ull << i)) && n->key_len[i] == f->lit_pos) {
                    f->idx = i + 1;
                    f->sub = i; // remember which prop for the value
                    f->phase = P_OBJ_COLON;
                    return 0;
                }
            }
            return -1;
        }
        uint64_t next = 0;
        for (int i = 0; i < n->n_props; i++)
            if ((f->alive & (1ull << i)) && f->lit_pos < n->key_len[i] &&
                n->keys[i][f->lit_pos] == (char)c)
                next |= 1ull << i;
        if (!next) return -1;
        f->alive = next;
        f->lit_pos++;
        return 0;
    }

    case P_OBJ_COLON:
        if (is_ws(c)) return 0;
        if (c != ':') return -1;
        f->phase = P_OBJ_NEXT; // resumed here after the child completes
        return push_value(v, n->kind == SN_MAP ? n->items : n->props[f->sub]) ? 0 : -1;

    case P_OBJ_NEXT:
        if (is_ws(c)) return 0;
        if (c == ',') {
            if (n->kind == SN_OBJ &&
                (f->idx >= n->n_props || !key_candidates(n, f->idx))) return -1;
            // FAIL CLOSED at guard capacity: a comma the guard could not
            // track would reopen the duplicate hole the guard exists to
            // close, so the map cannot grow past it — but `}` stays legal
            // here, so the model is never wedged, only bounded.
            if (n->kind == SN_MAP && v->n_seen >= MAP_SEEN_MAX) return -1;
            f->phase = P_OBJ_KEY;
            return 0;
        }
        if (c == '}') {
            if (n->kind == SN_OBJ && !close_allowed(n, f->idx)) return -1;
            frame_done(v);
            return 0;
        }
        return -1;

    case P_ARR_FIRST:
        if (is_ws(c)) return 0;
        if (c == ']') {
            if (n->min_items > 0) return -1;
            frame_done(v);
            return 0;
        }
        f->idx = 1;
        f->phase = P_ARR_NEXT;
        if (!push_value(v, n->items)) return -1;
        return feed_byte(v, c);

    case P_ARR_NEXT:
        if (is_ws(c)) return 0;
        if (c == ',') {
            if (n->max_items >= 0 && f->idx >= n->max_items) return -1;
            f->idx++;
            return push_value(v, n->items) ? 0 : -1;
        }
        if (c == ']') {
            if (f->idx < n->min_items) return -1;
            frame_done(v);
            return 0;
        }
        return -1;

    case P_SEQ:
        if (f->idx >= n->n_props) { frame_done(v); return 1; }
        return push_value(v, n->props[f->idx++]) ? feed_byte(v, c) : -1;

    case P_MEM_FIRST:
    case P_MEM_NEXT: {
        bool first = f->phase == P_MEM_FIRST;
        if (!f->alive) f->alive = member_candidates(n, f->idx);
        uint64_t next = 0;
        int completed = -1;
        int pending_completed = f->sub ? f->sub - 1 : -1;
        for (int i = f->idx; i <= n->n_props; i++) {
            if (!(f->alive & (1ull << i))) continue;
            const char *lit = member_prefix(n, i, first);
            int len = member_prefix_len(n, i, first);
            if (f->lit_pos >= len || lit[f->lit_pos] != (char)c) continue;
            if (f->lit_pos + 1 == len) completed = i;
            else next |= 1ull << i;
        }
        bool reconsume = false;
        int picked = completed;
        if (completed >= 0 && next == 0) {
            // the current byte completed the selected prefix
        } else if (!next) {
            if (pending_completed < 0) return -1;
            picked = pending_completed;
            reconsume = true; // c belongs to the selected member's value/parent
        } else {
            f->alive = next;
            f->sub = completed >= 0 ? (uint8_t)(completed + 1) : 0;
            f->lit_pos++;
            return 0;
        }
        if (picked == n->n_props) {
            frame_done(v);
            return reconsume ? 1 : 0;
        }
        f->idx = picked + 1;
        f->sub = (uint8_t)picked;
        f->phase = P_MEM_NEXT;
        f->alive = 0;
        f->lit_pos = 0;
        if (!push_value(v, n->props[picked])) return -1;
        return reconsume ? feed_byte(v, c) : 0;
    }

    case P_RAW: {
        if (n->n_lits && n->n_alts) {
            int matched=raw_prefix(n->lits[0],f->sub,c);
            if ((size_t)matched==strlen(n->lits[0])) {
                // Replace the raw frame in place; the marker was consumed,
                // and the next byte belongs to the constrained call body.
                *f=(sframe){.node=n->alts[0],.phase=P_SEQ};
                return 0;
            }
            f->sub=(uint8_t)matched;
        }
        const char *sentinel = n->sentinel;
        int pos = f->lit_pos;
        if (c == (uint8_t)sentinel[pos]) {
            if (++pos == n->sentinel_len) {
                frame_done(v);
                return 0;
            }
            f->lit_pos = pos;
            return 0;
        }
        // The match broke on `c`. What was seen is sentinel[0..pos-1] then c,
        // and a SHORTER prefix of the sentinel can still end there: feed
        // `<|end|><|start|>assistant<|channel|>` the bytes `<|end|><|end|>`
        // and the tenth byte breaks a nine-byte match while leaving `<|e`
        // live. Falling back to "1 if c starts the sentinel, else 0" steps
        // over that occurrence entirely, and the raw value then runs past the
        // terminator every plain search for those bytes would stop at.
        //
        // k is the longest prefix of the sentinel that is a suffix of what
        // was seen; the bytes before it are content. For a sentinel with no
        // repeated prefix this is exactly the old 1-or-0.
        int k = pos;
        while (k > 0 &&
               !(sentinel[k - 1] == (char)c &&
                 !memcmp(sentinel, sentinel + pos + 1 - k, (size_t)(k - 1))))
            k--;
        int added = pos + 1 - k;
        if (n->max_items >= 0 && f->idx + added > n->max_items) return -1;
        f->idx += added;
        f->lit_pos = k;
        return 0;
    }
    }
    return -1;
}

// Is whitespace at the current position CONTENT rather than separator?
//
// JSON permits insignificant whitespace between every token, so a validator
// accepts an all-whitespace token anywhere -- and a model that is unsure what
// to emit next will happily emit it until the budget is gone. Measured on
// e4b-q4km with a four-way tool schema: 253 of 377 output bytes were
// whitespace, in one 246-byte run, leaving 124 bytes of actual JSON. That is
// the "200 tokens of nothing" and "~150 blank lines" this program has twice
// filed as a schema defect.
//
// Suppressing insignificant whitespace cannot make any valid document
// unreachable, because it is optional everywhere it is legal. Inside a string
// it is NOT optional -- there it is the value -- so this reports that case and
// the caller leaves such tokens alone.
bool sval_raw_marker_opens(const sval *v, const char *spelling, int n) {
    if (v->depth <= 0 || n <= 0) return false;
    const sframe *f = &v->stack[v->depth - 1];
    if (!f->node || f->node->kind != SN_RAW || f->phase != P_RAW) return false;
    if (!f->node->n_lits || !f->node->n_alts) return false;
    const char *marker = f->node->lits[0];
    size_t ml = strlen(marker);
    int at = f->sub;
    for (int i = 0; i < n; i++) {
        if ((size_t)at >= ml) return true;   // the marker completed inside the spelling
        if ((unsigned char)spelling[i] != (unsigned char)marker[at]) return false;
        at++;
    }
    return at > f->sub;
}

bool sval_ws_is_content(const sval *v) {
    if (v->depth <= 0) return false;
    const sframe *f = &v->stack[v->depth - 1];
    if (!f->node) return false;
    // Protocol positions where whitespace is REQUIRED, not optional: an
    // atem_lit("\n") or a native member separator is spelled in whitespace,
    // and masking a whitespace-only token there can remove the only
    // reachable document on vocabularies without a combined token. The flag
    // is propagated onto the native containers at compile time because the
    // literal's own frame is pushed lazily, after the byte arrives.
    if (f->node->whitespace_significant) return true;
    // any-subtree runs its own machine; be conservative and treat its
    // whitespace as content rather than reach into it.
    if (f->node->kind == SN_ANY) return true;
    if (f->node->kind == SN_RAW && f->phase == P_RAW) return true;
    if (f->node->kind == SN_MAP && f->phase == P_OBJ_INKEY) return true;
    // Mid-string (P_STR with the opening quote consumed) is the content case.
    return f->phase == P_STR &&
           (f->node->kind == SN_STR || f->node->kind == SN_ENUM);
}

// Whether the validator is consuming FREE content (a raw value, a string
// body, a map key, an any-subtree), where a protocol marker the model spells
// as a control token would be corruption. This is the question the engine's
// control-token rule asks, and it is not sval_ws_is_content: that one also
// answers true at every whitespace-significant PROTOCOL position, which is
// the whole atem header (` to=`, the recipient enum, the invoke literal).
// Asking it there refused Muse's decoded-empty `<|message|>` right after the
// recipient name, so the served turn ended at the header with no call
// (measured 2026-09-16 on the fixture, `required` and `auto` alike).
bool sval_in_free_content(const sval *v) {
    if (v->depth <= 0) return false;
    const sframe *f = &v->stack[v->depth - 1];
    if (!f->node) return false;
    if (f->node->kind == SN_ANY) return true;
    if (f->node->kind == SN_RAW && f->phase == P_RAW) return true;
    if (f->node->kind == SN_MAP && f->phase == P_OBJ_INKEY) return true;
    return f->phase == P_STR &&
           (f->node->kind == SN_STR || f->node->kind == SN_ENUM);
}

bool sval_in_u_escape(const sval *v) {
    if (!v || v->done || v->depth <= 0) return false;
    const sframe *f = &v->stack[v->depth - 1];
    // only where `sub` is str_byte's escape progress
    if (!f->node) return false;
    if (!((f->phase == P_STR && f->node->kind == SN_STR) ||
          (f->phase == P_OBJ_INKEY && f->node->kind == SN_MAP)))
        return false;
    return (f->sub >= 2 && f->sub <= 5) || f->sub >= 8;
}

// A trailing raw node (Muse's to=user free-text answer) has no terminator
// the byte machine can ever see: its sentinel is the spelled form of the
// model's end-of-turn token, which decodes to no bytes when the model
// actually emits it. Report whether the validator sits inside such a tail —
// a raw frame (entered, or about to be entered as the last child) with only
// exhausted sequence frames above it — so the engine can accept a stop token
// there as the answer's natural end instead of forcing the branch to burn
// the whole token budget and finish "length".
bool sval_at_raw_tail(const sval *v) {
    if (!v || v->done || v->depth <= 0) return false;
    for (int i = 0; i < v->depth; i++) {
        const sframe *f = &v->stack[i];
        if (i == v->depth - 1) {
            if (f->node->kind == SN_RAW) return f->phase == P_RAW;
            // between the header literal and the answer's first byte the raw
            // child is not yet pushed; an empty answer is still an answer
            return f->node->kind == SN_SEQ && f->phase == P_SEQ &&
                   f->idx == f->node->n_props - 1 &&
                   f->node->props[f->idx]->kind == SN_RAW;
        }
        if (f->node->kind != SN_SEQ || f->idx < f->node->n_props)
            return false;
    }
    return false;
}

// The validator reads stack[0 .. depth-1] and nothing above it: push_value()
// assigns the whole frame at stack[depth] before depth names it, and every
// reader (feed_byte, frame_choice, frame_done, sval_close, the two query
// predicates) indexes depth-1 or less. The number spelling is likewise live
// only up to num_len, `any` carries its own live prefix, and the map
// seen-key guard is live up to n_seen. So a trial copy only has to carry
// those, which is what makes the per-candidate probe cheap.
//
// Anything added to this file that reads a stack slot above `depth`,
// num_text past num_len, or seen entries past n_seen, breaks this.
// test_sval_trial_matches_full_copy poisons the scratch and compares
// against a full struct copy from every state of a document -- the guard
// state included, not just the answer -- so it breaks loudly rather than
// subtly.
bool sval_trial(const sval *v, sval *scratch, const char *s, int n) {
    int d = v->depth;
    if (d < 0) d = 0;
    else if (d > (int)(sizeof(v->stack) / sizeof(v->stack[0])))
        d = (int)(sizeof(v->stack) / sizeof(v->stack[0]));
    memcpy(scratch->stack, v->stack, (size_t)d * sizeof(v->stack[0]));
    scratch->depth = v->depth;
    scratch->done = v->done;
    scratch->last_enum = v->last_enum;
    scratch->num_len = v->num_len;
    memcpy(scratch->num_text, v->num_text, (size_t)v->num_len + 1);
    int ns = v->n_seen;
    if (ns > MAP_SEEN_MAX) ns = MAP_SEEN_MAX;
    scratch->n_seen = (uint8_t)ns;
    memcpy(scratch->seen_hash, v->seen_hash,
           (size_t)ns * sizeof(v->seen_hash[0]));
    memcpy(scratch->seen_depth, v->seen_depth, (size_t)ns);
    jsonv_snapshot(&scratch->any, &v->any);
    return sval_feed(scratch, s, n);
}

bool sval_feed(sval *v, const char *s, int len) {
    for (int i = 0; i < len; i++) {
        int r = feed_byte(v, (uint8_t)s[i]);
        if (r < 0) return false;
        if (r == 1) { // reconsume in parent
            r = feed_byte(v, (uint8_t)s[i]);
            if (r < 0) return false;
            if (r == 1) return false; // double reconsume: shouldn't happen
        }
    }
    return true;
}

// ---------------------------------------------------------------- close

// `reserve` is headroom the FILL loops may not touch, so the structural tail
// behind them always fits. See sval_close, which sets it.
//
// `grow` marks a heap buffer the queue may enlarge (doubling, up to `max`),
// which is how sval_close_alloc keeps a close VALID whatever the schema asks
// for: a 5,000-character enum member, or minLength past the old fixed 4,096,
// used to come back cut at the buffer's end with no closing quote (external
// review, 2026-09-27). A fixed caller buffer keeps the old truncating shape.
typedef struct { char *out; int cap, n, reserve; bool grow; int max; } emitq;

// Room for `need` more bytes plus the NUL, enlarging a growable buffer when
// it must. False once the buffer is fixed or at its ceiling.
static bool eq_grow(emitq *q, int need) {
    if (q->n + need < q->cap) return true;
    if (!q->grow || q->cap >= q->max) return false;
    int nc = q->cap;
    while (nc <= q->n + need && nc < q->max)
        nc = nc > q->max / 2 ? q->max : nc * 2;
    char *p = realloc(q->out, (size_t)nc);
    if (!p) { q->grow = false; return false; }
    q->out = p;
    q->cap = nc;
    return q->n + need < q->cap;
}
static void eq_put(emitq *q, const char *s) {
    while (*s) {
        if (q->n >= q->cap - 1 && !eq_grow(q, 1)) break;
        q->out[q->n++] = *s++;
    }
}
static void eq_putc(emitq *q, char c) {
    if (q->n < q->cap - 1 || eq_grow(q, 1)) q->out[q->n++] = c;
}
// Once the buffer is full nothing further can be emitted, so the minItems /
// minLength loops below stop there. Without this they still iterate to the
// declared bound, and minItems:2000000000 (nested, worse) spins for minutes
// while a slot is held.
//
// They stop `reserve` bytes SHORT of full, because stopping at the last byte
// left no room for the `]` / `}` / `"` behind them and eq_putc dropped it
// silently: a `[` closed under minItems:5000 came back as 4095 filler bytes
// and no bracket at all. A document that parses and is short of its minItems
// is something a caller can read; one that does not parse is not.
static bool eq_full(emitq *q) {
    if (q->n + q->reserve >= q->cap - 1) eq_grow(q, q->reserve + 1);
    return q->n + q->reserve >= q->cap - 1;
}

// Finish the string escape generation stopped inside, if any. Shared with
// json_mode's closer so the two cannot disagree about what a partial escape
// completes to -- see json_escape_close. Reports whether it completed a
// CHARACTER, which the length accounting has not counted yet: feed_byte
// advances lit_pos only once an escape closes.
static bool eq_escape(emitq *q, sframe *f) {
    char esc[12];
    int n = json_escape_close(&f->sub, &f->esc, 0, esc, (int)sizeof(esc),
                              NULL);
    for (int i = 0; i < n; i++) eq_putc(q, esc[i]);
    return n > 0;
}

// A raw UTF-8 lead already consumed one code point. If truncation lands in
// its continuation bytes, finish that same scalar before writing the quote.
static void eq_utf8(emitq *q, sframe *f) {
    char u8[3];
    int n = json_utf8_close(&f->utf8_state, u8);
    for (int i = 0; i < n; i++) eq_putc(q, u8[i]);
}

// Minimal in-bounds number fill, emitted as CHECKED text: the clamped edge
// of an exclusive bound is one ULP inside it, and for exclusiveMinimum:0
// that edge is the smallest subnormal (4.94e-324) — in bounds by
// construction, refused by json_parse (ERANGE). When the edge spelling
// fails the shared predicate, scan decimal magnitudes for the smallest
// spelling that is both parseable and in bounds. A schema whose entire
// interval is unparseable (both edges subnormal) has no such spelling; the
// edge is emitted as the honest best effort.
static void emit_min_number(emitq *q, const snode *n) {
    double v = 0.0;
    if (n->has_real_min && v < n->real_min) v = n->real_min;
    if (n->has_real_max && v > n->real_max) v = n->real_max;
    if (v == 0.0) { eq_putc(q, '0'); return; }
    char b[40];
    snprintf(b, sizeof(b), "%.17g", v);
    if (!number_text_in_bounds(n, b)) {
        for (int mag = -307; mag <= 308; mag++) {
            for (int sign = 1; sign >= -1; sign -= 2) {
                char cand[40];
                snprintf(cand, sizeof(cand), "%s1e%d",
                         sign < 0 ? "-" : "", mag);
                if (number_text_in_bounds(n, cand)) {
                    eq_put(q, cand);
                    return;
                }
            }
        }
    }
    eq_put(q, b);
}

static int64_t integer_minimal_value(const snode *n) {
    if ((!n->has_num_min || n->num_min <= 0) &&
        (!n->has_num_max || n->num_max >= 0)) return 0;
    if (n->has_num_min && n->num_min > 0) return n->num_min;
    return n->num_max;
}

static void emit_integer(emitq *q, int64_t value) {
    char b[32];
    snprintf(b, sizeof(b), "%lld", (long long)value);
    eq_put(q, b);
}

// Complete an already-emitted integer prefix with the shortest suffix that
// lands inside the compiled interval. Prefix viability guarantees one exists.
static void close_integer(emitq *q, const snode *n, const sframe *f) {
    if (integer_in_bounds(n, f)) return;
    bool neg = f->lit_pos < 0;
    uint64_t prefix = f->num_abs;
    int64_t want_lo = n->has_num_min ? n->num_min : -JSON_SAFE_INTEGER;
    int64_t want_hi = n->has_num_max ? n->num_max :  JSON_SAFE_INTEGER;
    uint64_t scale = 10;
    for (int digits = 1; digits < 19; digits++) {
        if (prefix > (uint64_t)JSON_SAFE_INTEGER / scale) break;
        uint64_t low_abs = prefix * scale;
        uint64_t high_abs = low_abs + scale - 1;
        if (high_abs > (uint64_t)JSON_SAFE_INTEGER)
            high_abs = (uint64_t)JSON_SAFE_INTEGER;
        int64_t lo = neg ? -(int64_t)high_abs : (int64_t)low_abs;
        int64_t hi = neg ? -(int64_t)low_abs  : (int64_t)high_abs;
        if (ranges_intersect(lo, hi, want_lo, want_hi)) {
            int64_t target = lo < want_lo ? want_lo : lo;
            if (target > hi) target = hi;
            uint64_t target_abs = target < 0 ? (uint64_t)(-target) : (uint64_t)target;
            uint64_t suffix = target_abs - low_abs;
            char fmt[16], b[32];
            snprintf(fmt, sizeof(fmt), "%%0%dllu", digits);
            snprintf(b, sizeof(b), fmt, (unsigned long long)suffix);
            eq_put(q, b);
            return;
        }
        if (scale > (uint64_t)JSON_SAFE_INTEGER / 10) break;
        scale *= 10;
    }
}

// Finish a real number the model has already started, inside its interval.
//
// The digits are gone -- the client has them -- so the only lever left is the
// suffix, and JSON gives a decisive one: an exponent scales the value by any
// power of ten. That is also why the validator accepts these prefixes in the
// first place (`843584921` is a legal start for a value in [-3,9], via
// `843584921e-9`), so a close that stopped at the digits emitted a document
// which parsed and then violated the schema it was generated under. The
// caller cannot detect that; a bounded field is the one place it is entitled
// not to check.
//
// The exponent is SEARCHED and evaluated, not derived: every candidate is the
// exact text that will be emitted, run through the same bounds test the
// validator uses, so the emitted value is checked rather than argued.
static void close_number(emitq *q, const sval *v, const snode *n,
                         const sframe *f) {
    char spell[sizeof(v->num_text) + 8];
    int emitted = v->num_len;
    memcpy(spell, v->num_text, (size_t)emitted);
    spell[emitted] = 0;
    if (!emitted) {
        // nothing was generated: a bounded number closes to an in-bounds
        // value, not a blind zero — and to a spelling json_parse reads
        // back (an exclusive bound's clamped edge can be subnormal)
        emit_min_number(q, n);
        return;
    }
    int len = emitted;
    if (!num_complete(f->sub)) {   // `-`, `1.`, `1e`, `1e+`: one digit finishes it
        spell[len++] = '0';
        spell[len] = 0;
    }
    if (number_text_in_bounds(n, spell)) { eq_put(q, spell + emitted); return; }
    // An exponent can only be spelled once, so a prefix that already has one
    // has no lever left; everything else can be scaled.
    // Smallest |exponent| first, and up before down: the completion closest in
    // magnitude to the number the model actually wrote. Taking the first hit
    // of an ascending scan instead lands on a subnormal (`...e-330`), which
    // is in bounds, which json_parse then refuses for ERANGE.
    if (f->sub != N_EXP0 && f->sub != N_EXP1 && f->sub != N_EXP) {
        for (int mag = 1; mag <= 330; mag++) {
            for (int sign = 1; sign >= -1; sign -= 2) {
                char cand[sizeof(spell) + 8];
                int cn = snprintf(cand, sizeof(cand), "%se%d", spell,
                                  sign * mag);
                // the completed spelling must be one this validator would
                // accept back: number_put holds num_text minus its terminator
                if (cn < 0 || cn >= (int)sizeof(v->num_text)) continue;
                if (!number_text_in_bounds(n, cand)) continue;
                eq_put(q, cand + emitted);
                return;
            }
        }
    }
    eq_put(q, spell + emitted);   // no completion exists: keep it parseable
}

// minimal complete value for a schema node
static void emit_min_choice(emitq *q, const snode *n, int depth, int choice) {
    if (depth > 24) { eq_put(q, "null"); return; }
    if (n->kind == SN_COND) {
        const snode *alt = (choice >= 0 && choice < n->n_alts) ?
                           n->alts[choice] : n->alts[0];
        emit_min_choice(q, alt, depth + 1, choice);
        return;
    }
    switch (n->kind) {
        case SN_ANY:  eq_put(q, n->min_items ? "{}" : "null"); break;
        case SN_NULL: eq_put(q, "null"); break;
        case SN_BOOL: eq_put(q, "false"); break;
        case SN_NUM:
            // minimal value respects the declared bounds — a bounded number
            // filled in by force-close must still satisfy its own schema,
            // and be a spelling json_parse reads back (see emit_min_number)
            emit_min_number(q, n);
            break;
        case SN_INT: emit_integer(q, integer_minimal_value(n)); break;
        case SN_STR:
            eq_putc(q, '"');
            if (n->n_pats) {
                int need = pat_min_len(n);
                if (n->min_items > need) need = n->min_items;
                for (int i = 0; i < need && !eq_full(q); i++)
                    eq_putc(q, pat_fill_byte(n, i));
            } else {
                for (int i = 0; i < n->min_items && !eq_full(q); i++) eq_putc(q, ' ');
            }
            eq_putc(q, '"');
            break;
        case SN_ENUM: eq_put(q, n->lits[0]); break;
        case SN_UNION: {
            for (int i = 0; i < n->n_alts; i++)
                if (n->alts[i]->kind == SN_NULL) { eq_put(q, "null"); return; }
            emit_min_choice(q, n->alts[0], depth + 1, choice);
            break;
        }
        case SN_ARR:
            eq_putc(q, '[');
            for (int i = 0; i < n->min_items && !eq_full(q); i++) {
                if (i) eq_putc(q, ',');
                emit_min_choice(q, n->items, depth + 1, choice);
            }
            eq_putc(q, ']');
            break;
        case SN_OBJ: {
            eq_putc(q, '{');
            bool first = true;
            for (int i = 0; i < n->n_props; i++) {
                if (!n->req[i]) continue;
                if (!first) eq_putc(q, ',');
                first = false;
                eq_putc(q, '"'); eq_put(q, n->keys[i]); eq_put(q, "\":");
                // a fresh object emits its own discriminator as lits[0], so
                // any SN_COND inside must follow alternative 0, not `choice`
                emit_min_choice(q, n->props[i], depth + 1, 0);
            }
            eq_putc(q, '}');
            break;
        }
        case SN_MAP:
            eq_put(q, "{}");
            break;
        case SN_SEQ:
            for (int i = 0; i < n->n_props; i++) {
                emit_min_choice(q, n->props[i], depth + 1, choice);
                // A discriminator emitted HERE comes out as lits[0], so the
                // conditional after it must follow alternative 0 rather than
                // whatever the enclosing sequence chose. Without this an
                // inner tool name (get_weather) was emitted with the outer
                // channel's index, pairing it with a different tool's
                // arguments. Same reasoning as the SN_OBJ arm above.
                if (n->props[i]->kind == SN_ENUM && n->props[i]->min_items)
                    choice = 0;
            }
            break;
        case SN_MEMBERS: {
            bool first = true;
            for (int i = 0; i < n->n_props; i++) {
                if (!n->req[i]) continue;
                eq_put(q, member_prefix(n, i, first));
                emit_min_choice(q, n->props[i], depth + 1, choice);
                first = false;
            }
            eq_put(q, n->sentinel);
            break;
        }
        case SN_RAW:
            eq_put(q, n->sentinel);
            break;
        case SN_COND:
            break;
    }
}

// emit the remaining required properties of an object frame and close it.
// need_comma: a ',' must precede the first emitted property.
// force_one: at least one property must be emitted (a ',' was already
// consumed, so a bare '}' would be invalid JSON).
static void close_obj(emitq *q, const snode *n, int from, bool need_comma,
                      bool force_one, int choice) {
    bool emitted = false;
    for (int i = from; i < n->n_props; i++) {
        if (!n->req[i]) continue;
        if (need_comma) eq_putc(q, ',');
        need_comma = true;
        emitted = true;
        eq_putc(q, '"'); eq_put(q, n->keys[i]); eq_put(q, "\":");
        emit_min_choice(q, n->props[i], 0, choice);
    }
    if (force_one && !emitted && from < n->n_props) {
        eq_putc(q, '"'); eq_put(q, n->keys[from]); eq_put(q, "\":");
        emit_min_choice(q, n->props[from], 0, choice);
    }
    eq_putc(q, '}');
}

static void close_members(emitq *q, const snode *n, int from, bool first,
                          int choice) {
    for (int i = from; i < n->n_props; i++) {
        if (!n->req[i]) continue;
        eq_put(q, member_prefix(n, i, first));
        emit_min_choice(q, n->props[i], 0, choice);
        first = false;
    }
    eq_put(q, n->sentinel);
}

// An any-subtree frame: the generic machine closes what it opened.
static void close_any_frame(sval *v, emitq *q, const snode *n, const sframe *f) {
    if (f->phase == P_START) { emit_min_choice(q, n, 0, -1); return; }
    char tmp[512];
    int cn = jsonv_close(&v->any, tmp, sizeof(tmp));
    if (cn > 0) eq_put(q, tmp);
    else if (!v->any.done) eq_put(q, n->min_items ? "{}" : "null");
}

// A string frame: finish a pending escape or UTF-8 scalar, fill to the
// minimum length, close the quote.
static void close_string_frame(emitq *q, const snode *n, sframe *f) {
    // a dangling backslash or a partial \uXXXX. The character it
    // completes is one lit_pos never saw, and padding as if it were
    // still missing added one filler too many -- straight past
    // maxLength, into a document this grammar itself rejects.
    if (eq_escape(q, f)) f->lit_pos++;
    eq_utf8(q, f);
    int string_min = n->min_items;
    if (n->n_pats && string_min < pat_min_len(n))
        string_min = pat_min_len(n);
    while (f->lit_pos < string_min && !eq_full(q)) {
        eq_putc(q, n->n_pats ? pat_fill_byte(n, f->lit_pos) : ' ');
        f->lit_pos++;
    }
    eq_putc(q, '"');
}

// A literal frame (enum, boolean, null): finish the pending or first live
// literal, and let a finished discriminator decide its parent's choice.
static void close_literal_frame(sval *v, emitq *q, const snode *n, const sframe *f) {
    static const char *bools[] = { "true", "false" };
    static const char *nulls[] = { "null" };
    const char *const *lits = n->kind == SN_ENUM ? (const char *const *)n->lits :
                              n->kind == SN_BOOL ? bools : nulls;
    int cnt = n->kind == SN_ENUM ? n->n_lits : (n->kind == SN_BOOL ? 2 : 1);
    int pick = -1;
    if (n->kind == SN_ENUM) {
        // the completed literal if one is pending, else the first
        // live one in sorted order (the range the walker carries)
        int lo = (int)(uint32_t)f->alive, hi = (int)(f->alive >> 32);
        pick = f->idx > 0 ? f->idx - 1 : (lo < hi ? (n->order ? n->order[lo] : lo) : -1);
    } else {
        for (int i = 0; i < cnt; i++)
            if (f->alive & (1ull << i)) { pick = i; break; }
    }
    if (pick < 0) return;
    eq_put(q, lits[pick] + f->lit_pos);
    // Finishing a discriminator literal decides the parent's choice —
    // the args emitted next must come from the same alternative. Both
    // shapes frame_done() recognises are recognised here, or a turn
    // truncated inside the tool NAME closes with a different tool's
    // parameters: the object/args pair, and the ENUM+COND sequence
    // every native grammar (atem, Harmony, gemma4) is built from.
    if (n->kind == SN_ENUM && v->depth >= 2) {
        sframe *pf = &v->stack[v->depth - 2];
        if (pf->node->kind == SN_OBJ && pf->sub < pf->node->n_props &&
            !strcmp(pf->node->keys[pf->sub], "tool"))
            pf->disc = (uint16_t)(pick + 1);
        else if (pf->node->kind == SN_SEQ && n->min_items)
            pf->disc = (uint16_t)(pick + 1);
    }
}

// A map key forced closed at `kh`: extend it with '_' until its hash is
// fresh in this map, so the closed document never repeats a key the feed
// guard (and json_parse) refuses, then give it a value and close the map.
static void close_map_key(const sval *v, emitq *q, const snode *n, uint32_t kh,
                          int choice) {
    for (int extend = 0; extend < 64; extend++) {
        bool dup = false;
        for (int i = 0; i < v->n_seen; i++)
            if (v->seen_depth[i] == v->depth &&
                v->seen_hash[i] == kh) { dup = true; break; }
        if (!dup) break;
        eq_putc(q, '_');
        kh = json_key_hash_byte(kh, '_');
    }
    eq_put(q, "\":");
    emit_min_choice(q, n->items, 0, choice);
    eq_putc(q, '}');
}

// A key in progress: in a map, finish it as a fresh key; in an object,
// finish the lowest live candidate key, then the required rest.
static void close_inkey_frame(sval *v, emitq *q, const snode *n, sframe *f,
                              int choice) {
    if (n->kind == SN_MAP) {
        // a force-closed key must not complete into a duplicate the
        // feed guard refuses (and json_parse will refuse): finish
        // any pending escape or scalar while keeping the decoded
        // hash current, then extend the key until the hash is fresh
        uint32_t kh = (uint32_t)f->num_abs;
        char fin[12];
        uint32_t scalar = 0;
        int fn = json_escape_close(&f->sub, &f->esc,
                                   (uint16_t)(f->num_abs >> 32),
                                   fin, (int)sizeof(fin), &scalar);
        for (int i = 0; i < fn; i++) eq_putc(q, fin[i]);
        if (scalar) kh = json_key_hash_scalar(kh, scalar);
        fn = json_utf8_close(&f->utf8_state, fin);
        for (int i = 0; i < fn; i++) {
            eq_putc(q, fin[i]);
            kh = json_key_hash_byte(kh, (uint8_t)fin[i]);
        }
        close_map_key(v, q, n, kh, choice);
        return;
    }
    // finish the lowest still-alive candidate key, give it a value
    for (int i = 0; i < n->n_props; i++) {
        if (!(f->alive & (1ull << i))) continue;
        eq_put(q, n->keys[i] + f->lit_pos);
        eq_put(q, "\":");
        emit_min_choice(q, n->props[i], 0, choice);
        f->idx = i + 1;
        break;
    }
    close_obj(q, n, f->idx, true, false, choice);
}

// A native member list: finish the member in progress, then the required
// rest and the list's close.
static void close_member_frame(emitq *q, const snode *n, const sframe *f,
                               int choice) {
    bool first = f->phase == P_MEM_FIRST;
    if (f->lit_pos == 0) {
        close_members(q, n, f->idx, first, choice);
        return;
    }
    int pick = f->sub ? f->sub - 1 : -1;
    if (pick < 0) {
        for (int i = f->idx; i <= n->n_props; i++) {
            if (f->alive & (1ull << i)) { pick = i; break; }
        }
    }
    if (pick < 0) return;
    const char *prefix = member_prefix(n, pick, first);
    eq_put(q, prefix + f->lit_pos);
    if (pick == n->n_props) return;
    emit_min_choice(q, n->props[pick], 0, choice);
    close_members(q, n, pick + 1, false, choice);
}

static int sval_close_q(sval *v, emitq *q) {
    if (v->done) { q->out[0] = 0; return 0; }
    // Nothing generated at all — the root value never opened, so there is no
    // partial document to complete. Emit nothing.
    //
    // This branch used to synthesize a full minimal document instead, which
    // made an unproductive decode indistinguishable from a real answer: a
    // budget spent entirely on a reasoning prelude came back as
    // `{"progress":"","next_step":""}` with finish_reason "length", parsing
    // and conforming while carrying nothing the model actually produced.
    // Completing a document the model started is truncation; inventing one it
    // never started is fabrication, and a caller must be able to tell the
    // difference. jsonv_close has always drawn that line the same way.
    if (v->depth == 1 && v->stack[0].phase == P_START) {
        q->out[0] = 0;
        return 0;
    }
    while (v->depth > 0) {
        sframe *f = &v->stack[v->depth - 1];
        const snode *n = f->node;
        int choice = frame_choice(v, v->depth - 1);
        switch (n->kind == SN_ANY ? P_STR + 100 : f->phase) {
        case P_STR + 100: // any-subtree: let the generic machine close
            close_any_frame(v, q, n, f);
            break;
        case P_START:
            emit_min_choice(q, n, 0, choice);
            break;
        case P_STR:
            close_string_frame(q, n, f);
            break;
        case P_LIT:
            close_literal_frame(v, q, n, f);
            break;
        case P_NUM:
            if (n->kind == SN_INT) close_integer(q, n, f);
            else close_number(q, v, n, f);
            break;
        case P_OBJ_KEY1:
            if (n->kind == SN_MAP) eq_putc(q, '}');
            else close_obj(q, n, f->idx, false, false, choice);
            break;
        case P_OBJ_KEY: // a ',' was already consumed
            if (n->kind == SN_MAP) {
                // the invented key must dodge the duplicate guard: an
                // empty key may already exist in this map
                uint32_t kh = json_key_hash_init();
                eq_putc(q, '"');
                close_map_key(v, q, n, kh, choice);
            } else {
                close_obj(q, n, f->idx, false, true, choice);
            }
            break;
        case P_OBJ_INKEY:
            close_inkey_frame(v, q, n, f, choice);
            break;
        case P_OBJ_COLON:
            eq_putc(q, ':');
            emit_min_choice(q, n->kind == SN_MAP ? n->items : n->props[f->sub],
                            0, choice);
            if (n->kind == SN_MAP) eq_putc(q, '}');
            else close_obj(q, n, f->idx, true, false, choice);
            break;
        case P_OBJ_NEXT: // a value just completed, comma needed before more
            if (n->kind == SN_MAP) eq_putc(q, '}');
            else close_obj(q, n, f->idx, true, false, choice);
            break;
        case P_ARR_FIRST:
        case P_ARR_NEXT:
            for (int i = f->idx; i < n->min_items && !eq_full(q); i++) {
                if (i > 0 || f->phase == P_ARR_NEXT) eq_putc(q, ',');
                emit_min_choice(q, n->items, 0, -1);
            }
            eq_putc(q, ']');
            break;
        case P_SEQ:
            for (int i = f->idx; i < n->n_props && !eq_full(q); i++)
                emit_min_choice(q, n->props[i], 0, choice);
            break;
        case P_MEM_FIRST:
        case P_MEM_NEXT:
            close_member_frame(q, n, f, choice);
            break;
        case P_RAW:
            // Bytes already matching the sentinel are part of the generated
            // prefix; append only the unmatched suffix, then the enclosing
            // sequence contributes its fixed newline/invoke/calls closes.
            if (n->n_lits && n->n_alts && f->sub > f->lit_pos) {
                eq_put(q,n->lits[0]+f->sub);
                emit_min_choice(q,n->alts[0],0,choice);
            } else eq_put(q, n->sentinel + f->lit_pos);
            break;
        }
        v->depth--;
    }
    v->done = true;
    q->out[q->n] = 0;
    return q->n;
}

int sval_close(sval *v, char *out, int cap) {
    // One closing byte per frame still open, plus the one this frame writes
    // and the NUL. SVAL_MAX_DEPTH bounds v->depth, so this is a small fixed
    // reservation against a fill bound the request chose.
    emitq q = { out, cap, 0, v->depth + 2, false, cap };
    return sval_close_q(v, &q);
}

char *sval_close_alloc(sval *v, int *len, int max) {
    int cap = 4096;
    if (max < 64) max = 64;
    if (cap > max) cap = max;
    char *buf = malloc((size_t)cap);
    *len = 0;
    if (!buf) return NULL;
    emitq q = { buf, cap, 0, v->depth + 2, true, max };
    *len = sval_close_q(v, &q);
    return q.out;
}
